const rtdal002051Source0021 = `mask_function <- function(x, mask) {
  if (!is.call(x)) {
    return(x)
  }
  nms <- names(mask)
  x[-1] <- lapply(x[-1], mask_function, mask = mask)
  if (!is_call(x, nms)) {
    return(x)
  }
  for (nm in nms) {
    if (is_call(x, nm)) {
      x[[1]] <- mask[[nm]]
      return(x)
    }
  }
}`

