const rtdal002055Source0011 = `rename_aes <- function(x) {
  names(x) <- standardise_aes_names(names(x))
  duplicated_names <- names(x)[duplicated(names(x))]
  if (length(duplicated_names) > 0L) {
    cli::cli_warn("Duplicated aesthetics after name standardisation: {.field {unique0(duplicated_names)}}")
  }
  x
}`

const rtdal002055Source0012 = `substitute_aes <- function(x, fun = standardise_aes_symbols, ...) {
  x <- lapply(x, function(aesthetic) {
    as_quosure(fun(quo_get_expr(aesthetic), ...), env = environment(aesthetic))
  })
  class_mapping(x)
}`

const rtdal002055Source0016 = "aes_ <- function(x, y, ...) {\n  deprecate_warn0(\n    \"3.0.0\",\n    \"aes_()\",\n    details = \"Please use tidy evaluation idioms with `aes()`\"\n  )\n  mapping <- list(...)\n  if (!missing(x)) mapping[\"x\"] <- list(x)\n  if (!missing(y)) mapping[\"y\"] <- list(y)\n\n  caller_env <- parent.frame()\n\n  as_quosure_aes <- function(x) {\n    if (is_formula(x) && length(x) == 2) {\n      as_quosure(x)\n    } else if (is.null(x) || is.call(x) || is.name(x) || is.atomic(x)) {\n      new_aesthetic(x, caller_env)\n    } else {\n      cli::cli_abort(\"Aesthetic must be a one-sided formula, call, name, or constant.\")\n    }\n  }\n  mapping <- lapply(mapping, as_quosure_aes)\n  class_mapping(rename_aes(mapping))\n}"

const rtdal002055Source0017 = "aes_string <- function(x, y, ...) {\n  deprecate_warn0(\n    \"3.0.0\",\n    \"aes_string()\",\n    details = c(\n      \"Please use tidy evaluation idioms with `aes()`. \",\n      'See also `vignette(\"ggplot2-in-packages\")` for more information.'\n    )\n  )\n  mapping <- list(...)\n  if (!missing(x)) mapping[\"x\"] <- list(x)\n  if (!missing(y)) mapping[\"y\"] <- list(y)\n\n  caller_env <- parent.frame()\n  mapping <- lapply(mapping, function(x) {\n    if (is.character(x)) {\n      x <- parse_expr(x)\n    }\n    new_aesthetic(x, env = caller_env)\n  })\n\n  class_mapping(rename_aes(mapping))\n}"

const rtdal002055Source0019 = `aes_all <- function(vars) {
  names(vars) <- vars
  vars <- rename_aes(vars)

  # Quosure the symbols in the empty environment because they can only
  # refer to the data mask
  x <- class_mapping(lapply(vars, function(x) new_quosure(as.name(x), emptyenv())))
  class(x) <- union("unlabelled", class(x))
  x
}`

const rtdal002055Source0020 = `aes_auto <- function(data = NULL, ...) {
  lifecycle::deprecate_stop("2.0.0", "aes_auto()")
}`

const rtdal002055Source0023 = `warn_for_aes_extract_usage_expr <- function(x, data, env = emptyenv()) {
  if (is_call(x, "[[") || is_call(x, "$")) {
    if (extract_target_is_likely_data(x, data, env)) {
      good_usage <- alternative_aes_extract_usage(x)
      cli::cli_warn(c(
        "Use of {.code {format(x)}} is discouraged.",
        "i" = "Use {.code {good_usage}} instead."
      ))
    }
  } else if (is.call(x)) {
    lapply(x, warn_for_aes_extract_usage_expr, data, env)
  }
}`

const rtdal002055Source0024 = `alternative_aes_extract_usage <- function(x) {
  if (is_call(x, "[[")) {
    good_call <- call2("[[", quote(.data), x[[3]])
    format(good_call)
  } else if (is_call(x, "$")) {
    as.character(x[[3]])
  } else {
    cli::cli_abort("Don't know how to get alternative usage for {.var {x}}.")
  }
}`

const rtdal002055Source0025 = `extract_target_is_likely_data <- function(x, data, env) {
  if (!is.name(x[[2]]) || identical(x[[2]], quote(.data))) {
    return(FALSE)
  }

  tryCatch({
    data_eval <- eval_tidy(x[[2]], data, env)
    identical(unrowname(data_eval), unrowname(data))
  }, error = function(err) FALSE)
}`

