const rtdal002080Source0001 = `coord_transform <- function(x = "identity", y = "identity", xlim = NULL, ylim = NULL,
                            limx = deprecated(), limy = deprecated(), clip = "on",
                            expand = TRUE, reverse = "none") {
  if (lifecycle::is_present(limx)) {
    deprecate_warn0("3.3.0", "coord_transform(limx)", "coord_transform(xlim)")
    xlim <- limx
  }
  if (lifecycle::is_present(limy)) {
    deprecate_warn0("3.3.0", "coord_transform(limy)", "coord_transform(ylim)")
    ylim <- limy
  }

  check_coord_limits(xlim)
  check_coord_limits(ylim)

  # resolve transformers
  if (is.character(x)) x <- as.transform(x)
  if (is.character(y)) y <- as.transform(y)

  ggproto(
    NULL, CoordTransform,
    trans = list(x = x, y = y),
    limits = list(x = xlim, y = ylim),
    expand = expand,
    reverse = reverse,
    clip = clip
  )
}`

const rtdal002080Source0002 = `coord_trans <- function(...) {
  deprecate_soft0(
    "4.0.0",
    "coord_trans()",
    "coord_transform()"
  )
  coord_transform(...)
}`

const rtdal002080Source0003 = `CoordTransform <- ggproto(
  "CoordTransform", Coord,

  is_free = function() {
    TRUE
  },

  distance = function(self, x, y, panel_params) {
    max_dist <- dist_euclidean(panel_params$x.range, panel_params$y.range)
    dist_euclidean(self$trans$x$transform(x), self$trans$y$transform(y)) / max_dist
  },

  backtransform_range = function(self, panel_params) {
    list(
      x = self$trans$x$inverse(panel_params$x.range),
      y = self$trans$y$inverse(panel_params$y.range)
    )
  },

  range = function(self, panel_params) {
    list(
      x = panel_params$x.range,
      y = panel_params$y.range
    )
  },

  transform = function(self, data, panel_params) {
    # trans_x() and trans_y() needs to keep Inf values because this can be called
    # in guide_transform.axis()
    reverse <- panel_params$reverse %||% "none"
    x_range <- switch(reverse, xy = , x = rev, identity)(panel_params$x.range)
    y_range <- switch(reverse, xy = , y = rev, identity)(panel_params$y.range)
    trans_x <- function(data) {
      idx <- !is.infinite(data)
      data[idx] <- transform_value(self$trans$x, data[idx], x_range)
      data
    }
    trans_y <- function(data) {
      idx <- !is.infinite(data)
      data[idx] <- transform_value(self$trans$y, data[idx], y_range)
      data
    }

    new_data <- transform_position(data, trans_x, trans_y)

    warn_new_infinites(data$x, new_data$x, "x")
    warn_new_infinites(data$y, new_data$y, "y")

    transform_position(new_data, squish_infinite, squish_infinite)
  },

  setup_panel_params = function(self, scale_x, scale_y, params = list()) {
    c(
      view_scales_from_scale_with_coord_trans(scale_x, self$limits$x, self$trans$x, params$expand[c(4, 2)]),
      view_scales_from_scale_with_coord_trans(scale_y, self$limits$y, self$trans$y, params$expand[c(3, 1)]),
      reverse = self$reverse %||% "none"
    )
  },

  render_bg = function(self, panel_params, theme) {
    guide_grid(theme, panel_params, self)
  },

  render_axis_h = function(panel_params, theme) {
    list(
      top = panel_guides_grob(panel_params$guides, position = "top", theme = theme),
      bottom = panel_guides_grob(panel_params$guides, position = "bottom", theme = theme)
    )
  },

  render_axis_v = function(panel_params, theme) {
    list(
      left = panel_guides_grob(panel_params$guides, position = "left", theme = theme),
      right = panel_guides_grob(panel_params$guides, position = "right", theme = theme)
    )
  }
)`

const rtdal002080Source0005 = `transform_value <- function(trans, value, range) {
  if (is.null(value))
    return(value)
  rescale(trans$transform(value), 0:1, range)
}`

const rtdal002080Source0006 = "view_scales_from_scale_with_coord_trans <- function(scale, coord_limits, trans, expand = TRUE) {\n  expansion <- default_expansion(scale, expand = expand)\n  transformation <- scale$get_transformation() %||% transform_identity()\n  coord_limits <- coord_limits %||% transformation$inverse(c(NA, NA))\n  scale_limits <- scale$get_limits()\n\n  if (scale$is_discrete()) {\n    continuous_ranges <- expand_limits_discrete_trans(\n      scale$map(scale_limits),\n      expansion,\n      coord_limits,\n      trans,\n      range_continuous = scale$range_c$range\n    )\n  } else {\n    # transform user-specified limits to scale transformed space\n    coord_limits <- transformation$transform(coord_limits)\n    continuous_ranges <- expand_limits_continuous_trans(\n      scale_limits,\n      expansion,\n      coord_limits,\n      trans\n    )\n  }\n\n  # calculate break information\n  out <- scale$break_info(continuous_ranges$continuous_range)\n\n  # range in coord space has already been calculated\n  # needs to be in increasing order for transform_value() to work\n  out$range <- range(continuous_ranges$continuous_range_coord)\n\n  # major and minor values in coordinate data\n  out$major_source <- transform_value(trans, out$major_source, out$range)\n  out$minor_source <- transform_value(trans, out$minor_source, out$range)\n  out$sec.major_source <- transform_value(trans, out$sec.major_source, out$range)\n  out$sec.minor_source <- transform_value(trans, out$sec.minor_source, out$range)\n\n  out <- list(\n    # Note that a ViewScale requires a limit and a range that are before the\n    # Coord's transformation, so we pass `continuous_range`, not `continuous_range_coord`.\n    view_scale_primary(scale, scale_limits, continuous_ranges$continuous_range),\n    sec = view_scale_secondary(scale, scale_limits, continuous_ranges$continuous_range),\n    range = out$range,\n    labels = out$labels,\n    major = out$major_source,\n    minor = out$minor_source,\n    sec.labels = out$sec.labels,\n    sec.major = out$sec.major_source,\n    sec.minor = out$sec.minor_source\n  )\n\n  aesthetic <- scale$aesthetics[1]\n  names(out) <- c(aesthetic, paste(aesthetic, names(out)[-1], sep = \".\"))\n  out\n}"

const rtdal002080Source0007 = `warn_new_infinites <- function(old_values, new_values, axis, call = caller_env()) {
  if (any(is.finite(old_values) & !is.finite(new_values))) {
    cli::cli_warn("Transformation introduced infinite values in {axis}-axis", call = call)
  }
}`

