const rtdal002084Source0002 = "facet_grid <- function(rows = NULL, cols = NULL, scales = \"fixed\",\n                       space = \"fixed\", shrink = TRUE,\n                       labeller = \"label_value\", as.table = TRUE,\n                       switch = NULL, drop = TRUE, margins = FALSE,\n                       axes = \"margins\", axis.labels = \"all\",\n                       facets = deprecated()) {\n  # `facets` is deprecated\n  if (lifecycle::is_present(facets)) {\n    lifecycle::deprecate_stop(\"2.2.0\", \"facet_grid(facets)\", \"facet_grid(rows)\")\n  }\n\n  # Should become a warning in a future release\n  if (is.logical(cols)) {\n    margins <- cols\n    cols <- NULL\n  }\n\n  scales <- arg_match0(scales %||% \"fixed\", c(\"fixed\", \"free_x\", \"free_y\", \"free\"))\n  free <- list(\n    x = any(scales %in% c(\"free_x\", \"free\")),\n    y = any(scales %in% c(\"free_y\", \"free\"))\n  )\n\n  space <- arg_match0(space %||% \"fixed\", c(\"fixed\", \"free_x\", \"free_y\", \"free\"))\n  space_free <- list(\n    x = any(space %in% c(\"free_x\", \"free\")),\n    y = any(space %in% c(\"free_y\", \"free\"))\n  )\n\n  draw_axes <- arg_match0(axes, c(\"margins\", \"all_x\", \"all_y\", \"all\"))\n  draw_axes <- list(\n    x = any(draw_axes %in% c(\"all_x\", \"all\")),\n    y = any(draw_axes %in% c(\"all_y\", \"all\"))\n  )\n\n  # Omitting labels is special-cased internally, so even when no internal axes\n  # are to be drawn, register as labelled.\n  axis_labels <- arg_match0(axis.labels, c(\"margins\", \"all_x\", \"all_y\", \"all\"))\n  axis_labels <- list(\n    x = !draw_axes$x || any(axis_labels %in% c(\"all_x\", \"all\")),\n    y = !draw_axes$y || any(axis_labels %in% c(\"all_y\", \"all\"))\n  )\n\n  if (!is.null(switch)) {\n    arg_match0(switch, c(\"both\", \"x\", \"y\"))\n  }\n\n  facets_list <- grid_as_facets_list(rows, cols)\n\n  # Check for deprecated labellers\n  labeller <- validate_labeller(labeller)\n\n  ggproto(NULL, FacetGrid,\n    shrink = shrink,\n    params = list(rows = facets_list$rows, cols = facets_list$cols, margins = margins,\n      free = free, space_free = space_free, labeller = labeller,\n      as.table = as.table, switch = switch, drop = drop,\n      draw_axes = draw_axes, axis_labels = axis_labels)\n  )\n}"

const rtdal002084Source0003 = `grid_as_facets_list <- function(rows, cols) {
  is_rows_vars <- is.null(rows) || is_quosures(rows)
  if (!is_rows_vars) {
    if (!is.null(cols)) {
      msg <- "{.arg rows} must be {.code NULL} or a {.fn vars} list if {.arg cols} is a {.fn vars} list."
      # Native pipe have higher precedence than + so any type of gg object can be
      # expected here, not just ggplot
      if (S7::S7_inherits(rows, class_gg)) {
        msg <- c(
          msg,
          "i" = "Did you use {.code %>%} or {.code |>} instead of {.code +}?"
        )
      }
      cli::cli_abort(msg)
    }
    # For backward-compatibility
    facets_list <- as_facets_list(rows)
    if (length(facets_list) > 2L) {
      cli::cli_abort("A grid facet specification can't have more than two dimensions.")
    }
    # Fill with empty quosures
    facets <- list(rows = quos(), cols = quos())
    facets[seq_along(facets_list)] <- facets_list
    # Do not compact the legacy specs
    return(facets)
  }

  check_object(cols, is_quosures, "a {.fn vars} specification", allow_null = TRUE)

  list(
    rows = compact_facets(rows),
    cols = compact_facets(cols)
  )
}`

const rtdal002084Source0004 = `FacetGrid <- ggproto("FacetGrid", Facet,
  shrink = TRUE,

  compute_layout = function(self, data, params) {
    rows <- params$rows
    cols <- params$cols

    check_facet_vars(names(rows), names(cols), name = snake_class(self))

    dups <- intersect(names(rows), names(cols))
    if (length(dups) > 0) {
      cli::cli_abort(c(
              "Faceting variables can only appear in {.arg rows} or {.arg cols}, not both.",
        "i" = "Duplicated variables: {.val {dups}}"
      ), call = call2(snake_class(self)))
    }

    base_rows <- combine_vars(data, params$plot_env, rows, drop = params$drop)
    if (!params$as.table) {
      rev_order <- function(x) factor(x, levels = rev(ulevels(x)))
      base_rows[] <- lapply(base_rows, rev_order)
    }
    base_cols <- combine_vars(data, params$plot_env, cols, drop = params$drop)
    base <- df.grid(base_rows, base_cols)

    if (nrow(base) == 0) {
      return(data_frame0(
        PANEL = factor(1L),
        ROW = 1L,
        COL = 1L,
        SCALE_X = 1L,
        SCALE_Y = 1L
      ))
    }

    # Add margins
    base <- reshape_add_margins(base, list(names(rows), names(cols)), params$margins)
    base <- unique0(base)

    # Create panel info dataset
    panel <- id(base, drop = TRUE)
    panel <- factor(panel, levels = seq_len(attr(panel, "n")))

    rows <- if (!length(names(rows))) rep(1L, length(panel)) else id(base[names(rows)], drop = TRUE)
    cols <- if (!length(names(cols))) rep(1L, length(panel)) else id(base[names(cols)], drop = TRUE)

    panels <- data_frame0(PANEL = panel, ROW = rows, COL = cols, base)
    panels <- panels[order(panels$PANEL), , drop = FALSE]
    rownames(panels) <- NULL

    panels$SCALE_X <- if (params$free$x) panels$COL else 1L
    panels$SCALE_Y <- if (params$free$y) panels$ROW else 1L

    panels
  },

  map_data = map_facet_data,

  attach_axes = function(table, layout, ranges, coord, theme, params) {

    # Setup parameters
    draw_axes   <- params$draw_axes   %||% list(x = FALSE, y = FALSE)
    axis_labels <- params$axis_labels %||% list(x = TRUE,  y = TRUE)

    dim <- c(max(layout$ROW), max(layout$COL))
    if (!axis_labels$x) {
      cols    <- seq_len(nrow(layout))
      x_order <- as.integer(layout$PANEL[order(layout$ROW, layout$COL)])
    } else {
      cols    <- which(layout$ROW == 1)
      x_order <- layout$COL
    }
    if (!axis_labels$y) {
      rows    <- seq_len(nrow(layout))
      y_order <- as.integer(layout$PANEL[order(layout$ROW, layout$COL)])
    } else {
      rows    <- which(layout$COL == 1)
      y_order <- layout$ROW
    }

    # Render individual axes
    ranges <- censor_labels(ranges, layout, axis_labels)
    axes   <- render_axes(ranges[cols], ranges[rows], coord, theme, transpose = TRUE)
    mtx    <- function(x, o) matrix(x[o], dim[1], dim[2], byrow = TRUE)

    if (draw_axes$x) {
      table <- weave_axes(table, lapply(axes$x, mtx, o = x_order))
    } else {
      table <- seam_table(table, axes$x$top,    side = "top",    name = "axis-t", z = 3)
      table <- seam_table(table, axes$x$bottom, side = "bottom", name = "axis-b", z = 3)
    }

    if (draw_axes$y) {
      table <- weave_axes(table, lapply(axes$y, mtx, o = y_order))
    } else {
      table <- seam_table(table, axes$y$left,  side = "left",  name = "axis-l", z = 3)
      table <- seam_table(table, axes$y$right, side = "right", name = "axis-r", z = 3)
    }

    table
  },

  attach_strips = function(self, table, layout, params, theme) {

    strips <- self$format_strip_labels(layout, params)
    strips <- render_strips(strips$cols, strips$rows, theme = theme)

    padding <- convertUnit(calc_element("strip.switch.pad.grid", theme), "cm")

    switch_x <- !is.null(params$switch) && params$switch %in% c("both", "x")
    inside_x <- (calc_element("strip.placement.x", theme) %||% "inside") == "inside"
    shift_x  <- if (inside_x) 1 else 2

    if (switch_x) {
      space <- if (!inside_x & table_has_grob(table, "axis-b")) padding
      table <- seam_table(
        table, strips$x$bottom, side = "bottom", name = "strip-b",
        shift = shift_x, z = 2, clip = "off", spacing = space
      )
    } else {
      space <- if (!inside_x & table_has_grob(table, "axis-t")) padding
      table <- seam_table(
        table, strips$x$top, side = "top", name = "strip-t",
        shift = shift_x, z = 2, clip = "off", spacing = space
      )
    }

    switch_y <- !is.null(params$switch) && params$switch %in% c("both", "y")
    inside_y <- (calc_element("strip.placement.y", theme) %||% "inside") == "inside"
    shift_y  <- if (inside_y) 1 else 2

    if (switch_y) {
      space <- if (!inside_y & table_has_grob(table, "axis-l")) padding
      table <- seam_table(
        table, strips$y$left, side = "left", name = "strip-l",
        shift = shift_y, z = 2, clip = "off", spacing = space
      )
    } else {
      space <- if (!inside_y & table_has_grob(table, "axis-r")) padding
      table <- seam_table(
        table, strips$y$right, side = "right", name = "strip-r",
        shift = shift_y, z = 2, clip = "off", spacing = space
      )
    }
    table
  },

  vars = function(self) {
    names(c(self$params$rows, self$params$cols))
  },

  format_strip_labels = function(layout, params) {

    labeller <- match.fun(params$labeller)

    cols <- intersect(names(layout), names(params$cols))
    if (length(cols) > 0) {
      col_vars <- unique0(layout[cols])
      attr(col_vars, "type")  <- "cols"
      attr(col_vars, "facet") <- "grid"
      cols <- data_frame0(!!!labeller(col_vars))
    } else {
      cols <- NULL
    }

    rows <- intersect(names(layout), names(params$rows))
    if (length(rows) > 0) {
      row_vars <- unique0(layout[rows])
      attr(row_vars, "type")  <- "rows"
      attr(row_vars, "facet") <- "grid"
      rows <- data_frame0(!!!labeller(row_vars))
    } else {
      rows <- NULL
    }

    list(cols = cols, rows = rows)
  }
)`

const rtdal002084Source0005 = `ulevels <- function(x, na.last = TRUE) {
  if (is.factor(x)) {
    x <- addNA(x, TRUE)
    factor(levels(x), levels(x), exclude = NULL)
  } else {
    sort(unique0(x), na.last = na.last)
  }
}`

