const rtdal002088Source0001 = "fortify.lm <- function(model, data = model$model, ...) {\n  lifecycle::deprecate_warn(\n    \"4.0.0\", I(\"`fortify(<lm>)`\"), I(\"`broom::augment(<lm>)`\")\n  )\n  infl <- stats::influence(model, do.coef = FALSE)\n  data$.hat <- infl$hat\n  data$.sigma <- infl$sigma\n  data$.cooksd <- stats::cooks.distance(model, infl)\n\n  data$.fitted <- stats::predict(model)\n  data$.resid <- stats::resid(model)\n  data$.stdresid <- stats::rstandard(model, infl)\n\n  data\n}"

const rtdal002088Source0003 = "fortify.glht <- function(model, data, ...) {\n  lifecycle::deprecate_warn(\n    \"4.0.0\", I(\"`fortify(<glht>)`\"), I(\"`broom::tidy(<glht>)`\")\n  )\n  base::data.frame(\n    lhs = rownames(model$linfct),\n    rhs = model$rhs,\n    estimate = stats::coef(model),\n    check.names = FALSE,\n    stringsAsFactors = FALSE\n  )\n}"

const rtdal002088Source0004 = "fortify.confint.glht <- function(model, data, ...) {\n  lifecycle::deprecate_warn(\n    \"4.0.0\", I(\"`fortify(<confint.glht>)`\"), I(\"`broom::tidy(<confint.glht>)`\")\n  )\n  coef <- model$confint\n  colnames(coef) <- to_lower_ascii(colnames(coef))\n\n  base::data.frame(\n    lhs = rownames(coef),\n    rhs = model$rhs,\n    coef,\n    check.names = FALSE,\n    stringsAsFactors = FALSE\n  )\n}"

const rtdal002088Source0005 = "fortify.summary.glht <- function(model, data, ...) {\n  lifecycle::deprecate_warn(\n    \"4.0.0\", I(\"`fortify(<summary.glht>)`\"), I(\"`broom::tidy(<summary.glht>)`\")\n  )\n  coef <- as.data.frame(\n    model$test[c(\"coefficients\", \"sigma\", \"tstat\", \"pvalues\")])\n  names(coef) <- c(\"estimate\", \"se\", \"t\", \"p\")\n\n  base::data.frame(\n    lhs = rownames(coef),\n    rhs = model$rhs,\n    coef,\n    check.names = FALSE,\n    stringsAsFactors = FALSE\n  )\n}"

