const rtdal002135Source0001 = "ggproto <- function(`_class` = NULL, `_inherit` = NULL, ...) {\n  e <- new.env(parent = emptyenv())\n\n  members <- list2(...)\n  if (length(members) != sum(nzchar(names(members)))) {\n    cli::cli_abort(\"All members of a {.cls ggproto} object must be named.\")\n  }\n\n  # R <3.1.2 will error when list2env() is given an empty list, so we need to\n  # check length. https://github.com/tidyverse/ggplot2/issues/1444\n  if (length(members) > 0) {\n    list2env(members, envir = e)\n  }\n\n  # Dynamically capture parent: this is necessary in order to avoid\n  # capturing the parent at package build time.\n  `_inherit` <- substitute(`_inherit`)\n  env <- parent.frame()\n  find_super <- function() {\n    eval(`_inherit`, env, NULL)\n  }\n\n  super <- find_super()\n  if (!is.null(super)) {\n    check_object(super, is_ggproto, \"a {.cls ggproto} object\", arg = \"_inherit\")\n    e$super <- find_super\n    class(e) <- c(`_class`, class(super))\n  } else {\n    class(e) <- c(`_class`, \"ggproto\", \"gg\")\n  }\n\n  e\n}"

const rtdal002135Source0005 = `fetch_ggproto <- function(x, name) {
  res <- NULL

  val <- .subset2(x, name)
  # The is.null check is an optimization for a common case; exists() also
  # catches the case where the value exists but has a NULL value.
  if (!is.null(val) || exists(name, envir = x, inherits = FALSE)) {
    res <- val
  } else {
    # If not found here, recurse into super environments
    super <- .subset2(x, "super")
    if (is.null(super)) {
      # no super class
    } else if (is.function(super)) {
      res <- fetch_ggproto(super(), name)
    } else {
      cli::cli_abort(c(
        "{class(x)[[1]]} was built with an incompatible version of ggproto.",
        "i" = "Please reinstall the package that provides this extension."
      ))
    }
  }

  res
}`

const rtdal002135Source0006 = `.DollarNames.ggproto <- function(x, pattern = "") {
  methods <- ls(envir = x)
  if ("super" %in% methods) {
    methods <- setdiff(methods, "super")
    methods <- union(methods, Recall(x$super()))
  }

  if (identical(pattern, "")) {
    methods
  } else {
    grep(pattern, methods, value = TRUE)
  }

}`

const rtdal002135Source0009 = "make_proto_method <- function(self, f, name) {\n  args <- formals(f)\n  # is.null is a fast path for a common case; the %in% check is slower but also\n  # catches the case where there's a `self = NULL` argument.\n  has_self  <- !is.null(args[[\"self\"]]) || \"self\"  %in% names(args)\n\n  # We assign the method with its correct name and construct a call to it to\n  # make errors reported as coming from the method name rather than `f()`\n  assign(name, f, envir = environment())\n  args <- list(quote(...))\n  if (has_self) {\n    args$self <- quote(self)\n  }\n  fun <- inject(function(...) !!call2(name, !!!args))\n\n  class(fun) <- \"ggproto_method\"\n  fun\n}"

const rtdal002135Source0011 = `as.list.ggproto <- function(x, inherit = TRUE, ...) {
  res <- list()

  if (inherit) {
    if (is.function(x$super)) {
      res <- as.list(x$super())
    }
  }

  current <- as.list.environment(x, ...)
  res[names(current)] <- current
  res$super <- NULL
  res
}`

const rtdal002135Source0012 = `print.ggproto <- function(x, ..., flat = TRUE) {
  if (is.function(x$print)) {
    x$print(...)

  } else {
    cat(format(x, flat = flat), "\n", sep = "")
    invisible(x)
  }
}`

const rtdal002135Source0013 = `format.ggproto <-  function(x, ..., flat = TRUE) {
  classes_str <- function(obj) {
    classes <- setdiff(class(obj), "ggproto")
    if (length(classes) == 0)
      return("")
    paste0(": Class ", paste(classes, collapse = ', '))
  }

  # Get a flat list if requested
  if (flat) {
    objs <- as.list(x, inherit = TRUE)
  } else {
    objs <- x
  }

  str <- paste0(
    "<ggproto object", classes_str(x), ">\n",
    indent(object_summaries(objs, flat = flat), 4)
  )

  if (flat && is.function(x$super)) {
    str <- paste0(
      str, "\n",
      indent(
        paste0("super: ", " <ggproto object", classes_str(x$super()), ">"),
        4
      )
    )
  }

  str
}`

const rtdal002135Source0017 = `print.ggproto_method <- function(x, ...) {
  cat(format(x), sep = "")
}`

const rtdal002135Source0018 = `format.ggproto_method <- function(x, ...) {

  # Given a function, return a string from srcref if present. If not present,
  # paste the deparsed lines of code together.
  format_fun <- function(fn) {
    srcref <- attr(fn, "srcref", exact = TRUE)
    if (is.null(srcref))
      return(paste(format(fn), collapse = "\n"))

    paste(as.character(srcref), collapse = "\n")
  }

  x <- unclass(x)
  paste0(
    "<ggproto method>",
    "\n  <Wrapper function>\n    ", format_fun(x),
    "\n\n  <Inner function (f)>\n    ", format_fun(environment(x)$f)
  )
}`

const rtdal002135Source0020 = `ggproto_debug <- function(method, debug = c("once", "always", "never"), ...) {
  if (inherits(method, "ggproto_method")) {
    method <- environment(method)$f
  }
  check_function(method)
  switch(
    arg_match0(debug, c("once", "always", "never")),
    once   = debugonce(method, ...),
    always = debug(method, ...),
    never  = undebug(method, ...)
  )
}`

