const rtdal002158Source0001 = `update_labels <- function(p, labels) {
  p <- plot_clone(p)
  p@labels <- labs(!!!defaults(labels, p@labels))
  p
}`

const rtdal002158Source0002 = "setup_plot_labels <- function(plot, layers, data) {\n  # Initiate empty labels\n  labels <- list()\n\n  # Find labels from every layer\n  for (i in seq_along(layers)) {\n    layer <- layers[[i]]\n\n    mapping <- layer$computed_mapping\n    if (inherits(mapping, \"unlabelled\")) {\n      next\n    }\n    mapping <- mapping[have_name(mapping)]\n\n    mapping <- strip_stage(mapping)\n    mapping <- strip_dots(mapping, strip_pronoun = TRUE)\n\n    exclude <- names(layer$aes_params)\n    mapping <- mapping[setdiff(names(mapping), exclude)]\n\n    # Acquire default labels\n    mapping_default <- make_labels(mapping)\n    stat_default <- lapply(\n      make_labels(layer$stat$default_aes),\n      function(l) {\n        attr(l, \"fallback\") <- TRUE\n        l\n      }\n    )\n    default <- defaults(mapping_default, stat_default)\n\n    # Search for label attribute in symbolic mappings\n    symbolic <- vapply(\n      mapping, FUN.VALUE = logical(1),\n      function(x) is_quosure(x) && quo_is_symbol(x)\n    )\n    symbols <- intersect(names(mapping)[symbolic], names(data[[i]]))\n    attribs <- lapply(setNames(nm = symbols), function(x) {\n      attr(data[[i]][[x]], \"label\", exact = TRUE)\n    })\n    attribs <- attribs[lengths(attribs) > 0]\n    layer_labels <- defaults(attribs, default)\n\n    # Set label priority:\n    # 1. Existing labels that aren't fallback labels\n    # 2. The labels of this layer, including fallback labels\n    # 3. Existing fallback labels\n    current <- labels\n    fallbacks <- vapply(current, function(l) isTRUE(attr(l, \"fallback\")), logical(1))\n\n    labels <- defaults(current[!fallbacks], layer_labels)\n    if (any(fallbacks)) {\n      labels <- defaults(labels, current)\n    }\n  }\n\n  # Warn for spurious labels that don't have a mapping.\n  # Note: sometimes, 'x' and 'y' might not have a mapping, like in\n  # `geom_function()`. We can display these labels anyway, so we include them.\n  plot_labels  <- plot@labels\n  known_labels <- c(names(labels), fn_fmls_names(labs), \"x\", \"y\")\n  extra_labels <- names(plot_labels)[lengths(plot_labels) > 0]\n  extra_labels <- setdiff(extra_labels, known_labels)\n\n  if (length(extra_labels) > 0) {\n\n    warn_labels <- plot_labels[extra_labels]\n    warn_labels <- ifelse(\n      vapply(warn_labels, is.function, logical(1)),\n      \"{.cls function}\",\n      paste0(\"{.val \", warn_labels, \"}\")\n    )\n\n    extra_labels <- paste0(\"{.field \", extra_labels, \"} : \", warn_labels)\n    names(extra_labels) <- rep(\"*\", length(extra_labels))\n\n    cli::cli_inform(c(\n      \"Ignoring unknown labels:\",\n      extra_labels\n    ))\n  }\n\n  # User labels can be functions, so apply these to the default labels\n  plot_labels <- lapply(setNames(nm = names(plot_labels)), function(nm) {\n    label <- plot_labels[[nm]]\n    if (!is.function(label)) {\n      return(label)\n    }\n    label(labels[[nm]] %||% \"\")\n  })\n\n  dict <- plot_labels$dictionary\n  if (length(dict) > 0) {\n    labels <- lapply(labels, function(x) {\n      dict <- dict[names(dict) %in% x]\n      x[match(names(dict), x)] <- dict\n      x\n    })\n  }\n\n  labs(!!!defaults(plot_labels, labels))\n}"

const rtdal002158Source0004 = `labs <- function(..., title = waiver(), subtitle = waiver(),
                 caption = waiver(), tag = waiver(), dictionary = waiver(),
                 alt = waiver(), alt_insight = waiver()) {
  # .ignore_empty = "all" is needed to allow trailing commas, which is NOT a trailing comma for dots_list() as it's in ...
  args <- dots_list(..., title = title, subtitle = subtitle, caption = caption,
                    tag = tag, alt = allow_lambda(alt), alt_insight = alt_insight,
                    dictionary = dictionary, .ignore_empty = "all")

  is_waive <- vapply(args, is_waiver, logical(1))
  args <- args[!is_waive]
  # remove duplicated arguments
  args <- args[!duplicated(names(args))]
  args <- rename_aes(args)
  class_labels(args)
}`

const rtdal002158Source0005 = `xlab <- function(label) {
  lifecycle::signal_stage("superseded", "xlab()", "labs(x)")
  labs(x = label)
}`

const rtdal002158Source0006 = `ylab <- function(label) {
  lifecycle::signal_stage("superseded", "ylab()", "labs(y)")
  labs(y = label)
}`

const rtdal002158Source0007 = `ggtitle <- function(label, subtitle = waiver()) {
  lifecycle::signal_stage("superseded", "ggtitle()", I("labs(title, subtitle)"))
  labs(title = label, subtitle = subtitle)
}`

const rtdal002158Source0008 = `get_labs <- function(plot = get_last_plot()) {
  plot <- ggplot_build(plot)

  labs <- plot@plot@labels

  xy_labs <- rename(
    c(x = plot@layout$resolve_label(plot@layout$panel_scales_x[[1]], labs),
      y = plot@layout$resolve_label(plot@layout$panel_scales_y[[1]], labs)),
    c(x.primary = "x", x.secondary = "x.sec",
      y.primary = "y", y.secondary = "y.sec")
  )

  labs <- defaults(xy_labs, labs)

  guides <- plot@plot@guides
  if (length(guides$aesthetics) == 0) {
    return(labs)
  }

  for (aes in guides$aesthetics) {
    param <- guides$get_params(aes)
    aes   <- param$aesthetic # Can have length > 1 when guide was merged
    title <- vec_set_names(rep(list(param$title), length(aes)), aes)
    labs  <- defaults(title, labs)
  }
  labs
}`

const rtdal002158Source0009 = `get_alt_text <- S7::new_generic("get_alt_text", "p", fun = function(p, ...) {
  warn_dots_used()
  S7::S7_dispatch()
})`

const rtdal002158Source0010 = `S7::method(get_alt_text, class_ggplot) <- function(p, ...) {
  alt <- p@labels[["alt"]] %||% ""
  if (!is.function(alt)) {
    return(alt)
  }
  p@labels[["alt"]] <- NULL
  build <- ggplot_build(p)
  build@plot@labels[["alt"]] <- alt
  get_alt_text(build)
}`

const rtdal002158Source0011 = `S7::method(get_alt_text, class_ggplot_built) <- function(p, ...) {
  alt <- p@plot@labels[["alt"]] %||% ""
  p@plot@labels[["alt"]] <- NULL
  if (is.function(alt)) alt(p@plot) else alt
}`

const rtdal002158Source0012 = `S7::method(get_alt_text, class_gtable) <- function(p, ...) {
  attr(p, "alt-label") %||% ""
}`

const rtdal002158Source0015 = `scale_description <- function(p, name) {
  scale <- p@scales$get_scales(name)
  if (is.null(scale)) {
    lab <- p@labels[[name]]
    type <- "the"
  } else {
    lab <- scale$make_title(scale$name %|W|% p@labels[[name]])
    type <- "a continuous"
    if (scale$is_discrete()) type <- "a discrete"
    if (inherits(scale, "ScaleBinned")) type <- "a binned"
  }
  if (is.null(lab)) {
    return(NULL)
  }
  paste0(lab, " on ", type, " ", name, "-axis")
}`

