const rtdal002170Source0007 = `local({
  S7::method(print, class_ggplot) <- S7::method(plot, class_ggplot) <-
    function(x, newpage = is.null(vp), vp = NULL, ...) {
      set_last_plot(x)
      if (newpage) grid.newpage()

      # Record dependency on 'ggplot2' on the display list
      # (AFTER grid.newpage())
      grDevices::recordGraphics(
        requireNamespace("ggplot2", quietly = TRUE),
        list(),
        getNamespace("ggplot2")
      )

      data <- ggplot_build(x)

      gtable <- ggplot_gtable(data)
      if (is.null(vp)) {
        grid.draw(gtable)
      } else {
        if (is.character(vp)) seekViewport(vp) else pushViewport(vp)
        grid.draw(gtable)
        upViewport()
      }

      if (isTRUE(getOption("BrailleR.VI")) && rlang::is_installed("BrailleR")) {
        print(asNamespace("BrailleR")$VI(x))
      }

      invisible(x)
    }
})`

const rtdal002170Source0008 = "local({\n  S7::method(`[[`, class_gg) <- S7::method(`$`, class_gg) <-\n    function(x, i) {\n      if (!S7::prop_exists(x, i) && S7::prop_exists(x, \"meta\")) {\n        # This is a trick to bridge a gap between S3 and S7. We're allowing\n        # for arbitrary fields by reading/writing to the 'meta' field when the\n        # index does not point to an actual property.\n        # The proper way to go about this is to implement new fields as properties\n        # of a ggplot subclass.\n        S7::prop(x, \"meta\")[[i]]\n      } else {\n        `[[`(S7::props(x), i)\n      }\n    }\n  S7::method(`[`, class_gg) <- function(x, i) {\n    `[`(S7::props(x), i)\n  }\n})"

const rtdal002170Source0009 = "`[<-.ggplot2::gg` <- function(x, i, value) {\n  S7::props(x) <- `[<-`(S7::props(x), i, value)\n  x\n}"

const rtdal002170Source0010 = "`$<-.ggplot2::gg` <- function(x, i, value) {\n  if (!S7::prop_exists(x, i) && S7::prop_exists(x, \"meta\")) {\n    # See explanation in accessor\n    S7::prop(x, \"meta\")[[i]] <- value\n  } else {\n    S7::props(x) <- `[[<-`(S7::props(x), i, value)\n  }\n  x\n}"

const rtdal002170Source0012 = `local({
  S7::method(convert, list(from = class_ggplot, to = S7::class_list)) <-
    function(from, to) {
      S7::props(from)
    }

  S7::method(as.list, class_ggplot) <-
    function(x, ...) convert(x, S7::class_list)
})`

