const rtdal002180Source0001 = `property_boolean <- function(allow_null = FALSE, default = TRUE) {
  class <- S7::class_logical
  class <- if (allow_null) S7::new_union(class, NULL) else class
  validator <- function(value) {
    if ((allow_null && is.null(value)) || is_bool(value)) {
      return(character())
    }
    "must be a boolean"
  }
  S7::new_property(
    class = class,
    validator = validator,
    default = default
  )
}`

const rtdal002180Source0002 = `property_choice <- function(options, allow_null = FALSE, default = NULL) {
  force(options)
  class <- S7::class_character
  class <- if (allow_null) S7::new_union(class, NULL) else class
  validator <- function(value) {
    if (allow_null && is.null(value)) {
      return(character())
    }
    if (!is_character(value)) {
      return(as_cli("must be a string, not {.obj_type_friendly {value}}"))
    }
    if (all(value %in% options)) {
      return(character())
    }
    as_cli("must be one of {.or {.val {options}}}")
  }
  S7::new_property(
    class = class,
    validator = validator,
    default = default
  )
}`

const rtdal002180Source0003 = `property_fontface <- function(allow_null = TRUE, default = NULL) {
  options <- c("plain", "bold", "italic", "oblique", "bold.italic")
  class <- S7::new_union(S7::class_character, S7::class_numeric)
  class <- if (allow_null) S7::new_union(class, NULL) else class
  validator <- function(value) {
    if (allow_null && is.null(value)) {
      return(character())
    }
    if (is_integerish(value) && all(value %in% 1:4)) {
      return(character())
    }
    if (all(value %in% options)) {
      return(character())
    }
    as_cli("must be one of {.or {.val {options}}}.")
  }
  S7::new_property(
    class = class,
    validator = validator,
    default = default
  )
}`

const rtdal002180Source0004 = `property_nullable <- function(class = S7::class_any, ...) {
  S7::new_property(
    class = S7::new_union(NULL, class),
    ...
  )
}`

const rtdal002180Source0005 = "property_colour <- function(\n  allow_null = TRUE,\n  pattern = FALSE,\n  default = NULL\n) {\n  # TODO: remove numeric option for editioning\n  class <- S7::new_union(\n    S7::class_character, # Hex codes and colour names, e.g. #FF000 or \"red\"\n    S7::class_logical,   # For allowing NA, which means 'transparent'\n    S7::class_numeric    # For `grDevices::palette()` indexing\n  )\n  if (isTRUE(pattern)) {\n    class <- S7::new_union(class, S7::new_S3_class(\"GridPattern\"))\n  }\n  if (isTRUE(allow_null)) {\n    class <- S7::new_union(class, NULL)\n  }\n  validator <- function(value) {\n    if (is.numeric(value) && !is_integerish(value)) {\n      return(\"cannot be a decimal number, but could be an integer.\")\n    }\n    character()\n  }\n  S7::new_property(\n    class = class,\n    validator = validator,\n    default = default\n  )\n}"

