const rtdal002183Source0001 = `ggsave <- function(filename, plot = get_last_plot(),
                   device = NULL, path = NULL, scale = 1,
                   width = NA, height = NA, units = c("in", "cm", "mm", "px"),
                   dpi = 300, limitsize = TRUE, bg = NULL,
                   create.dir = FALSE,
                   ...) {
  filename <- validate_path(path, filename, create.dir)

  dpi <- parse_dpi(dpi)
  dev <- validate_device(device, filename, dpi = dpi)
  dim <- plot_dim(c(width, height), scale = scale, units = units,
    limitsize = limitsize, dpi = dpi)
  bg  <- get_plot_background(plot, bg)

  old_dev <- grDevices::dev.cur()
  dev(filename = filename, width = dim[1], height = dim[2], bg = bg, ...)
  on.exit(utils::capture.output({
    grDevices::dev.off()
    if (old_dev > 1) grDevices::dev.set(old_dev) # restore old device unless null device
  }))
  if (!is_bare_list(plot)) {
    plot <- list(plot)
  }
  lapply(plot, grid.draw)

  invisible(filename)
}`

const rtdal002183Source0002 = `validate_path <- function(path, filename, create.dir,
                          call = caller_env()) {

  if (length(filename) > 1 && is.character(filename)) {
    cli::cli_warn(c(
      "{.arg filename} must have length 1, not {length(filename)}.",
      "!" = "Only the first, {.file {filename[1]}}, will be used."
    ), call = call)
    filename <- filename[1]
  }
  check_string(filename, allow_empty = FALSE, call = call)

  check_string(path, allow_empty = FALSE, allow_null = TRUE, call = call)
  if (!is.null(path)) {
    filename <- file.path(path, filename)
  } else {
    path <- dirname(filename)
  }

  # Happy path: target file is in valid directory
  if (dir.exists(path)) {
    return(filename)
  }

  check_bool(create.dir, call = call)

  # Try to ask user to create a new directory
  if (interactive() && !create.dir) {
    cli::cli_bullets(c(
      "Cannot find directory {.path {path}}.",
      "i" = "Would you like to create a new directory?"
    ))
    create.dir <- utils::menu(c("Yes", "No")) == 1
  }

  # Create new directory
  if (create.dir) {
    dir.create(path, recursive = TRUE)
    if (dir.exists(path)) {
      cli::cli_alert_success("Created directory: {.path {path}}.")
      return(filename)
    }
  }

  cli::cli_abort(c(
    "Cannot find directory {.path {path}}.",
    i = "Please supply an existing directory or use {.code create.dir = TRUE}."
  ), call = call)
}`

const rtdal002183Source0003 = `parse_dpi <- function(dpi, call = caller_env()) {
  if (is_scalar_character(dpi)) {
    arg_match0(dpi, c("screen", "print", "retina"), error_call = call)

    switch(dpi,
      screen = 72,
      print = 300,
      retina = 320,
    )
  } else if (is_bare_numeric(dpi, n = 1L)) {
    dpi
  } else {
    stop_input_type(dpi, "a single number or string", call = call)
  }
}`

const rtdal002183Source0004 = "plot_dim <- function(dim = c(NA, NA), scale = 1, units = \"in\",\n                     limitsize = TRUE, dpi = 300, call = caller_env()) {\n  units <- arg_match0(units, c(\"in\", \"cm\", \"mm\", \"px\"))\n  to_inches <- function(x) x / c(`in` = 1, cm = 2.54, mm = 2.54 * 10, px = dpi)[units]\n  from_inches <- function(x) x * c(`in` = 1, cm = 2.54, mm = 2.54 * 10, px = dpi)[units]\n\n  dim <- to_inches(dim) * scale\n\n  if (anyNA(dim)) {\n    if (length(grDevices::dev.list()) == 0) {\n      default_dim <- c(7, 7)\n    } else {\n      default_dim <- grDevices::dev.size() * scale\n    }\n    dim[is.na(dim)] <- default_dim[is.na(dim)]\n    dim_f <- prettyNum(from_inches(dim), digits = 3)\n\n    cli::cli_inform(\"Saving {dim_f[1]} x {dim_f[2]} {units} image\")\n  }\n\n  if (limitsize && any(dim >= 50)) {\n    units <- switch(\n      units,\n      \"in\" = \"inches\",\n      \"cm\" = \"centimeters\",\n      \"mm\" = \"millimeters\",\n      \"px\" = \"pixels\"\n    )\n    msg <- paste0(\n      \"Dimensions exceed 50 inches ({.arg height} and {.arg width} are \",\n      \"specified in {.emph {units}}\"\n    )\n    if (units == \"pixels\") {\n      msg <- paste0(msg, \").\")\n    } else {\n      msg <- paste0(msg, \" not pixels).\")\n    }\n    cli::cli_abort(c(\n      msg,\n      \"i\" = \"If you're sure you want a plot that big, use {.code limitsize = FALSE}.\n    \"), call = call)\n  }\n\n  dim\n}"

const rtdal002183Source0005 = `get_plot_background <- function(plot, bg = NULL, default = "transparent") {
  if (!is.null(bg)) {
    return(bg)
  }
  plot <- if (is_bare_list(plot)) plot[[1]] else plot
  if (!is_ggplot(plot)) {
    return(default)
  }
  bg <- calc_element("plot.background", plot_theme(plot))
  try_prop(bg, "fill") %||% "transparent"
}`

const rtdal002183Source0006 = "validate_device <- function(device, filename = NULL, dpi = 300, call = caller_env()) {\n  force(filename)\n  force(dpi)\n\n  if (is.function(device)) {\n    args <- formals(device)\n    call_args <- list()\n    if (\"file\" %in% names(args)) {\n      call_args$file <- filename\n      call_args[\"filename\"] <- list(NULL)\n    }\n    if (\"res\" %in% names(args)) {\n      call_args$res <- dpi\n    }\n    if (\"units\" %in% names(args)) {\n      call_args$units <- 'in'\n    }\n    dev <- function(...) {\n      args <- modify_list(list(...), call_args)\n      inject(device(!!!args))\n    }\n    return(dev)\n  }\n\n  eps <- function(filename, ...) {\n    grDevices::postscript(file = filename, ..., onefile = FALSE, horizontal = FALSE,\n      paper = \"special\")\n  }\n  if (requireNamespace('ragg', quietly = TRUE)) {\n    png_dev <- absorb_grdevice_args(ragg::agg_png)\n    jpeg_dev <- absorb_grdevice_args(ragg::agg_jpeg)\n    tiff_dev <- absorb_grdevice_args(ragg::agg_tiff)\n  } else {\n    png_dev <- grDevices::png\n    jpeg_dev <- grDevices::jpeg\n    tiff_dev <- grDevices::tiff\n  }\n  devices <- list(\n    eps =  eps,\n    ps =   eps,\n    tex =  function(filename, ...) grDevices::pictex(file = filename, ...),\n    pdf =  function(filename, ..., version = \"1.4\") grDevices::pdf(file = filename, ..., version = version),\n    svg =  function(filename, ...) {\n      check_installed(\"svglite\", reason = \"to save as SVG.\")\n      svglite::svglite(file = filename, ...)\n    },\n    # win.metafile() doesn't have `bg` arg so we need to absorb it before passing `...`\n    emf =  function(..., bg = NULL) grDevices::win.metafile(...),\n    wmf =  function(..., bg = NULL) grDevices::win.metafile(...),\n    png =  function(...) png_dev(..., res = dpi, units = \"in\"),\n    jpg =  function(...) jpeg_dev(..., res = dpi, units = \"in\"),\n    jpeg = function(...) jpeg_dev(..., res = dpi, units = \"in\"),\n    bmp =  function(...) grDevices::bmp(..., res = dpi, units = \"in\"),\n    tiff = function(...) tiff_dev(..., res = dpi, units = \"in\"),\n    tif  = function(...) tiff_dev(..., res = dpi, units = \"in\")\n  )\n\n  if (is.null(device)) {\n    device <- to_lower_ascii(tools::file_ext(filename))\n    if (identical(device, \"\")) {\n      cli::cli_abort(c(\n        \"Can't save to {filename}.\",\n        i = \"Either supply {.arg filename} with a file extension or supply {.arg device}.\"),\n        call = call)\n    }\n  }\n\n  if (!is.character(device) || length(device) != 1) {\n    stop_input_type(device, \"a string, function\", allow_null = TRUE, call = call)\n  }\n\n  dev <- devices[[device]]\n  if (is.null(dev)) {\n    cli::cli_abort(\"Unknown graphics device {.val {device}}\", call = call)\n  }\n  dev\n}"

const rtdal002183Source0007 = `S7::method(grid.draw, class_ggplot) <- function(x, recording = TRUE) print(x)`

const rtdal002183Source0008 = `absorb_grdevice_args <- function(f) {
  function(..., type, antialias) {
    if (!missing(type) || !missing(antialias)) {
      cli::cli_warn("Using ragg device as default. Ignoring {.arg type} and {.arg antialias} arguments")
    }
    f(...)
  }
}`

