const rtdal002218Source0001 = `StatDensity <- ggproto(
  "StatDensity", Stat,
  required_aes = "x|y",

  default_aes = aes(x = after_stat(density), y = after_stat(density), fill = NA, weight = NULL),

  dropped_aes = "weight",

  setup_params = function(self, data, params) {
    params$flipped_aes <- has_flipped_aes(data, params, main_is_orthogonal = FALSE, main_is_continuous = TRUE)

    has_x <- !(is.null(data$x) && is.null(params$x))
    has_y <- !(is.null(data$y) && is.null(params$y))
    if (!has_x && !has_y) {
      cli::cli_abort("{.fn {snake_class(self)}} requires an {.field x} or {.field y} aesthetic.")
    }

    params
  },

  extra_params = c("na.rm", "orientation"),

  compute_group = function(data, scales, bw = "nrd0", adjust = 1, kernel = "gaussian",
                           n = 512, trim = FALSE, na.rm = FALSE, bounds = c(-Inf, Inf),
                           flipped_aes = FALSE) {
    data <- flip_data(data, flipped_aes)
    if (trim) {
      range <- range(data$x, na.rm = TRUE)
    } else {
      range <- scales[[flipped_names(flipped_aes)$x]]$dimension()
    }

    density <- compute_density(data$x, data$weight, from = range[1],
                               to = range[2], bw = bw, adjust = adjust, kernel = kernel, n = n,
                               bounds = bounds)
    density$flipped_aes <- flipped_aes
    flip_data(density, flipped_aes)
  }
)`

const rtdal002218Source0003 = `compute_density <- function(x, w, from, to, bw = "nrd0", adjust = 1,
                            kernel = "gaussian", n = 512,
                            bounds = c(-Inf, Inf)) {
  nx <- w_sum <- length(x)
  if (is.null(w)) {
    w <- rep(1 / nx, nx)
  } else {
    w_sum <- sum(w)
    w <- w / w_sum
  }

  # Adjust data points and weights to all fit inside bounds
  sample_data <- fit_data_to_bounds(bounds, x, w)
  x <- sample_data$x
  w <- sample_data$w
  w_sum <- sample_data$w_sum * w_sum
  nx <- length(x)

  # if less than 2 points return data frame of NAs and a warning
  if (nx < 2) {
    cli::cli_warn("Groups with fewer than two data points have been dropped.")
    return(data_frame0(
      x = NA_real_,
      density = NA_real_,
      scaled = NA_real_,
      ndensity = NA_real_,
      count = NA_real_,
      wdensity = NA_real_,
      n = NA_integer_,
      .size = 1
    ))
  }

  bw <- precompute_bw(x, bw)
  # Decide whether to use boundary correction
  if (any(is.finite(bounds))) {
    # To prevent discontinuities, we widen the range before calling the
    # unbounded estimator (#5641).
    bounds   <- sort(bounds)
    range    <- range(from, to)
    width    <- diff(range)
    range[1] <- range[1] - width * as.numeric(is.finite(bounds[1]))
    range[2] <- range[2] + width * as.numeric(is.finite(bounds[2]))
    n <- n * (sum(is.finite(bounds)) + 1)

    dens <- stats::density(
      x, weights = w, bw = bw, adjust = adjust,
      kernel = kernel, n = n, from = range[1], to = range[2]
    )
    dens <- reflect_density(
      dens = dens, bounds = bounds,
      from = range[1], to = range[2]
    )
  } else {
    dens <- stats::density(x, weights = w, bw = bw, adjust = adjust,
                           kernel = kernel, n = n, from = from, to = to)
  }

  data_frame0(
    x = dens$x,
    density = dens$y,
    scaled =  dens$y / max(dens$y, na.rm = TRUE),
    ndensity = dens$y / max(dens$y, na.rm = TRUE),
    count =   dens$y * nx,
    wdensity = dens$y * w_sum,
    n = nx,
    .size = length(dens$x)
  )
}`

const rtdal002218Source0004 = "fit_data_to_bounds <- function(bounds, x, w) {\n  is_inside_bounds <- (bounds[1] <= x) & (x <= bounds[2])\n  w_sum <- 1\n  if (!all(is_inside_bounds)) {\n    cli::cli_warn(\"Some data points are outside of `bounds`. Removing them.\")\n    x <- x[is_inside_bounds]\n    w <- w[is_inside_bounds]\n    w_sum <- sum(w)\n    if (w_sum > 0) {\n      w <- w / w_sum\n    }\n  }\n\n  return(list(x = x, w = w, w_sum = w_sum))\n}"

const rtdal002218Source0005 = "reflect_density <- function(dens, bounds, from, to) {\n  # No adjustment is needed if no finite bounds are supplied\n  if (all(is.infinite(bounds))) {\n    return(dens)\n  }\n\n  # Estimate linearly with zero tails (crucial to account for infinite bound)\n  f_dens <- stats::approxfun(\n    x = dens$x, y = dens$y, method = \"linear\", yleft = 0, yright = 0\n  )\n\n  # Create a uniform x-grid inside `bounds`\n  left <- max(from, bounds[1])\n  right <- min(to, bounds[2])\n  out_x <- seq(from = left, to = right, length.out = length(dens$x))\n\n  # Update density estimation by adding reflected tails from outside `bounds`\n  left_reflection <- f_dens(bounds[1] + (bounds[1] - out_x))\n  right_reflection <- f_dens(bounds[2] + (bounds[2] - out_x))\n  out_y <- f_dens(out_x) + left_reflection + right_reflection\n\n  list(x = out_x, y = out_y)\n}"

const rtdal002218Source0006 = "precompute_bw <- function(x, bw = \"nrd0\") {\n  bw <- bw[1]\n  if (is.character(bw)) {\n    bw <- to_lower_ascii(bw)\n    bw <- arg_match0(bw, c(\"nrd0\", \"nrd\", \"ucv\", \"bcv\", \"sj\", \"sj-ste\", \"sj-dpi\"))\n    bw <- switch(\n      to_lower_ascii(bw),\n      nrd0 = stats::bw.nrd0(x),\n      nrd  = stats::bw.nrd(x),\n      ucv  = stats::bw.ucv(x),\n      bcv  = stats::bw.bcv(x),\n      sj   = ,\n      `sj-ste` = stats::bw.SJ(x, method = \"ste\"),\n      `sj-dpi` = stats::bw.SJ(x, method = \"dpi\")\n    )\n  }\n  if (!is.numeric(bw) || bw <= 0 || !is.finite(bw)) {\n    cli::cli_abort(\n      \"{.arg bw} must be a finite, positive number, not {obj_type_friendly(bw)}.\"\n    )\n  }\n  bw\n}"

