const rtdal002242Source0019 = `print.rel <- function(x, ...) print(noquote(paste(x, " *", sep = "")))`

const rtdal002242Source0021 = `element_render <- function(theme, element, ..., name = NULL) {

  # Get the element from the theme, calculating inheritance
  el <- calc_element(element, theme)
  if (is.null(el)) {
    cli::cli_inform("Theme element {.var {element}} is missing")
    return(zeroGrob())
  }

  grob <- element_grob(el, ...)
  ggname(paste(element, name, sep = "."), grob)
}`

const rtdal002242Source0022 = `element_grob <- function(element, ...) {
  # TODO: Swap to S7 generic once S7/#543 is resolved
  UseMethod("element_grob")
}`

const rtdal002242Source0023 = `S7::method(element_grob, element_blank) <- function(element, ...) zeroGrob()`

const rtdal002242Source0024 = `S7::method(element_grob, element_rect) <-
  function(element, x = 0.5, y = 0.5, width = 1, height = 1,
           fill = NULL, colour = NULL,
           linewidth = NULL, linetype = NULL, linejoin = NULL,
           ..., size = deprecated()) {

    if (lifecycle::is_present(size)) {
      deprecate_warn0("3.4.0", "element_grob.element_rect(size)", "element_grob.element_rect(linewidth)")
      linewidth <- size
    }

    gp <- gg_par(lwd = linewidth, col = colour, fill = fill, lty = linetype, linejoin = linejoin)
    element_gp <- gg_par(lwd = element@linewidth, col = element@colour,
                         fill = element@fill, lty = element@linetype,
                         linejoin = element@linejoin)

    rectGrob(x, y, width, height, gp = modify_list(element_gp, gp), ...)
  }`

const rtdal002242Source0025 = `S7::method(element_grob, element_text) <-
  function(element, label = "", x = NULL, y = NULL,
           family = NULL, face = NULL, colour = NULL, size = NULL,
           hjust = NULL, vjust = NULL, angle = NULL, lineheight = NULL,
           margin = NULL, margin_x = FALSE, margin_y = FALSE, ...) {

    if (is.null(label)) {
      return(zeroGrob())
    }
    if (is_theme_element(label)) {
      cli::cli_warn("{.arg label} cannot be {.obj_type_friendly {label}}.")
      return(zeroGrob())
    }

    vj <- vjust %||% element@vjust
    hj <- hjust %||% element@hjust
    margin <- margin %||% element@margin

    angle <- angle %||% element@angle %||% 0

    # The gp settings can override element_gp
    gp <- gg_par(fontsize = size, col = colour,
                 fontfamily = family, fontface = face,
                 lineheight = lineheight)
    element_gp <- gg_par(fontsize = element@size, col = element@colour,
                         fontfamily = element@family, fontface = element@face,
                         lineheight = element@lineheight)

    titleGrob(label, x, y, hjust = hj, vjust = vj, angle = angle,
              gp = modify_list(element_gp, gp), margin = margin,
              margin_x = margin_x, margin_y = margin_y, debug = element@debug, ...)
  }`

const rtdal002242Source0026 = `S7::method(element_grob, element_line) <-
  function(element, x = 0:1, y = 0:1,
           colour = NULL, linewidth = NULL, linetype = NULL, lineend = NULL,
           linejoin = NULL, arrow.fill = NULL,
           default.units = "npc", id.lengths = NULL, ..., size = deprecated()) {

    if (lifecycle::is_present(size)) {
      deprecate_warn0("3.4.0", "element_grob.element_line(size)", "element_grob.element_line(linewidth)")
      linewidth <- size
    }

    arrow <- if (is.logical(element@arrow) && !element@arrow) {
      NULL
    } else {
      element@arrow
    }
    if (is.null(arrow)) {
      arrow.fill <- colour
      element@arrow.fill <- element@colour
    }

    # The gp settings can override element_gp
    gp <- gg_par(
      col = colour, fill = arrow.fill %||% colour,
      lwd = linewidth, lty = linetype, lineend = lineend, linejoin = linejoin
    )
    element_gp <- gg_par(
      col = element@colour, fill = element@arrow.fill %||% element@colour,
      lwd = element@linewidth, lty = element@linetype,
      lineend = element@lineend, linejoin = element@linejoin
    )

    polylineGrob(
      x, y, default.units = default.units,
      gp = modify_list(element_gp, gp),
      id.lengths = id.lengths, arrow = arrow, ...
    )
  }`

const rtdal002242Source0027 = "S7::method(element_grob, element_polygon) <-\n  function(element, x = c(0, 0.5, 1, 0.5),\n           y = c(0.5, 1, 0.5, 0), fill = NULL,\n           colour = NULL, linewidth = NULL,\n           linetype = NULL, linejoin = NULL, ...,\n           id = NULL, id.lengths = NULL,\n           pathId = NULL, pathId.lengths = NULL) {\n\n    gp <- gg_par(lwd = linewidth, col = colour, fill = fill,\n                 lty = linetype, linejoin = linejoin)\n    element_gp <- gg_par(lwd = element@linewidth, col = element@colour,\n                         fill = element@fill, lty = element@linetype,\n                         linejoin = element@linejoin)\n    pathGrob(\n      x = x, y = y, gp = modify_list(element_gp, gp), ...,\n      # We swap the id logic so that `id` is always the (super)group id\n      # (consistent with `polygonGrob()`) and `pathId` always the subgroup id.\n      pathId = id, pathId.lengths = id.lengths,\n      id = pathId, id.lengths = pathId.lengths\n    )\n  }"

const rtdal002242Source0028 = `S7::method(element_grob, element_point) <-
  function(element, x = 0.5, y = 0.5, colour = NULL,
           shape = NULL, fill = NULL, size = NULL,
           stroke = NULL, ...,
           default.units = "npc") {

    gp <- gg_par(col = colour, fill = fill, pointsize = size, stroke = stroke)
    element_gp <- gg_par(col = element@colour, fill = element@fill,
                         pointsize = element@size, stroke = element@stroke)
    shape <- translate_shape_string(shape %||% element@shape %||% 19)
    pointsGrob(x = x, y = y, pch = shape, gp = modify_list(element_gp, gp),
               default.units = default.units, ...)
  }`

const rtdal002242Source0029 = `register_theme_elements <- function(..., element_tree = NULL, complete = TRUE) {
  old <- ggplot_global$theme_default
  t <- theme(..., complete = complete)
  ggplot_global$theme_default <- ggplot_global$theme_default %+replace% t

  check_element_tree(element_tree)

  # Merge element trees
  ggplot_global$element_tree <- defaults(element_tree, ggplot_global$element_tree)

  invisible(old)
}`

const rtdal002242Source0030 = `reset_theme_settings <- function(reset_current = TRUE) {
  ggplot_global$element_tree <- .element_tree

  # reset the underlying fallback default theme
  ggplot_global$theme_default <- theme_grey()

  if (isTRUE(reset_current)) {
    # reset the currently active theme
    ggplot_global$theme_current <- ggplot_global$theme_default
  }
}`

const rtdal002242Source0031 = `on_load({
  ggplot_global$theme_all_null <- theme_all_null() # cache all null theme, required by theme_grey()
  ggplot_global$theme_current <- NULL  # the current theme applied to plots if none is specified
  ggplot_global$theme_default <- NULL  # the underlying fallback default theme
  ggplot_global$element_tree <- NULL   # the current element tree for themes
  reset_theme_settings() # sets the preceding three global variables to their actual defaults
})`

const rtdal002242Source0033 = "check_element_tree <- function(x, arg = caller_arg(x), call = caller_env()) {\n  check_object(x, is_bare_list, \"a bare {.cls list}\", arg = arg, call = call)\n  if (length(x) < 1) {\n    return(invisible(NULL))\n  }\n\n  if (!is_named(x)) {\n    cli::cli_abort(\"{.arg {arg}} must have names.\", call = call)\n  }\n\n  # All elements should be constructed with `el_def()`\n  fields <- names(el_def())\n  bad_fields <- !vapply(x, function(el) all(fields %in% names(el)), logical(1))\n  if (any(bad_fields)) {\n    bad_fields <- names(x)[bad_fields]\n    cli::cli_abort(\n      c(\"{.arg {arg}} must have elements constructed with {.fn el_def}.\",\n        i = \"Invalid structure: {.and {.val {bad_fields}}}\"),\n      call = call\n    )\n  }\n\n  # Check element tree, prevent elements from being their own parent (#6162)\n  bad_parent <- unlist(Map(\n    function(name, el) any(name %in% el$inherit),\n    name = names(x), el = x\n  ))\n  if (any(bad_parent)) {\n    bad_parent <- names(x)[bad_parent]\n    cli::cli_abort(\n      \"Invalid parent in {.arg {arg}}: {.and {.val {bad_parent}}}.\",\n      call = call\n    )\n  }\n  invisible(NULL)\n}"

const rtdal002242Source0036 = "check_element <- function(el, elname, element_tree, call = caller_env()) {\n  eldef <- element_tree[[elname]]\n\n  if (is.null(eldef)) {\n    cli::cli_warn(\"The {.var {elname}} theme element is not defined in the element hierarchy.\", call = call)\n    return()\n  }\n\n  # NULL values for elements are OK\n  if (is.null(el)) return()\n\n  class <- eldef$class\n  if (inherits(class, \"S7_class\")) {\n    inherit_ok <- S7::S7_inherits(el, class)\n    # For backward compatibility\n    # TODO: deprecate next release cycle\n    old_s3_inherits <- inherits(el, class@name)\n    inherit_ok <- inherit_ok || old_s3_inherits\n  } else {\n    inherit_ok <- inherits(el, class)\n  }\n\n  if (is.character(class) && any(c(\"margin\", \"ggplot2::margin\") %in% class)) {\n    if (\"rel\" %in% class && is_rel(el)) {\n      return()\n    }\n    if (is.unit(el) && length(el) == 4) {\n      return()\n    }\n    cli::cli_abort(\n      \"The {.var {elname}} theme element must be a {.cls unit} vector of length 4\",\n      call = call\n    )\n  }\n\n  # Maybe we should check that `class` is an element class before approving of\n  # blank elements?\n  if (inherit_ok || is_theme_element(el, \"blank\")) {\n    return()\n  }\n\n  class_name <- if (inherits(class, \"S7_class\")) class@name else class\n  cli::cli_abort(\n    \"The {.var {elname}} theme element must be a {.cls {class_name}} object.\",\n    call = call\n  )\n}"

