const rtdal002244Source0002 = "fix_theme_deprecations <- function(elements) {\n  if (is.unit(elements$legend.margin) && !is_margin(elements$legend.margin)) {\n    cli::cli_warn(c(\n      \"{.var legend.margin} must be specified using {.fn margin}\",\n      \"i\" = \"For the old behavior use {.var legend.spacing}\"\n    ))\n    elements$legend.spacing <- elements$legend.margin\n    elements$legend.margin <- margin()\n  }\n  if (!is.null(elements$legend.title.align)) {\n    deprecate_soft0(\n      \"3.5.0\", \"theme(legend.title.align)\",\n      I(\"theme(legend.title = element_text(hjust))\")\n    )\n    if (is.null(elements[[\"legend.title\"]])) {\n      elements$legend.title <- element_text(hjust = elements$legend.title.align)\n    } else if (!is_theme_element(elements$legend.title, \"blank\")) {\n      elements$legend.title$hjust <-\n        try_prop(elements$legend.title, \"hjust\", elements$legend.title.align)\n    }\n    elements$legend.title.align <- NULL\n  }\n  if (!is.null(elements$legend.text.align)) {\n    deprecate_soft0(\n      \"3.5.0\", \"theme(legend.text.align)\",\n      I(\"theme(legend.text = element_text(hjust))\")\n    )\n    if (is.null(elements[[\"legend.text\"]])) {\n      elements$legend.text <- element_text(hjust = elements$legend.text.align)\n    } else if (!is_theme_element(elements$legend.text, \"blank\")) {\n      elements$legend.text$hjust <-\n        try_prop(elements$legend.text, \"hjust\", elements$legend.text.align)\n    }\n    elements$legend.text.align <- NULL\n  }\n  if (is.numeric(elements[[\"legend.position\"]])) {\n    deprecate_soft0(\n      \"3.5.0\", I(\"A numeric `legend.position` argument in `theme()`\"),\n      \"theme(legend.position.inside)\"\n    )\n    elements$legend.position.inside <- elements$legend.position\n    elements$legend.position <- \"inside\"\n  }\n  elements\n}"

const rtdal002244Source0003 = `validate_theme_palettes <- function(elements) {

  pals <- c("palette.colour.discrete", "palette.colour.continuous",
            "palette.fill.discrete",   "palette.fill.continuous",
            "palette.color.discrete",  "palette.color.continuous")
  if (!any(pals %in% names(elements))) {
    return(elements)
  }

  # Standardise spelling
  if ("palette.color.continuous" %in% names(elements)) {
    elements["palette.colour.continuous"]  <- elements["palette.color.continuous"]
    elements[["palette.color.continuous"]] <- NULL
  }
  if ("palette.color.discrete" %in% names(elements)) {
    elements["palette.colour.discrete"]  <- elements["palette.color.discrete"]
    elements[["palette.color.discrete"]] <- NULL
  }

  # Check for incompatible options
  pals <- c("palette.colour.discrete", "palette.colour.continuous",
            "palette.fill.discrete",   "palette.fill.continuous")
  opts <- c("ggplot2.discrete.colour", "ggplot2.continuous.colour",
            "ggplot2.discrete.fill",   "ggplot2.continuous.fill")
  index <- which(pals %in% names(elements))

  for (i in index) {
    if (is.null(getOption(opts[i]))) {
      next
    }
    cli::cli_warn(c(
      "The {.code options('{opts[i]}')} setting is incompatible with the \\
        {.arg {pals[i]}} theme setting.",
      i = "You can set {.code options({opts[i]} = NULL)}."
    ))
  }

  elements
}`

const rtdal002244Source0004 = `is_theme <- function(x) S7::S7_inherits(x, class_theme)`

const rtdal002244Source0009 = `complete_theme <- function(theme = NULL, default = theme_get()) {
  if (!is_bare_list(theme)) {
    check_object(theme, is_theme, "a {.cls theme} object", allow_null = TRUE)
  }
  check_object(default, is_theme, "a {.cls theme} object")
  theme <- plot_theme(list(theme = theme), default = default)
  theme@complete <- TRUE
  theme@validate <- FALSE
  theme
}`

const rtdal002244Source0010 = "plot_theme <- function(x, default = get_theme()) {\n  if (S7::S7_inherits(x)) {\n    theme <- x@theme\n  } else {\n    theme <- x$theme\n  }\n\n\n  # apply theme defaults appropriately if needed\n  if (is_theme_complete(theme)) {\n    # for complete themes, we fill in missing elements but don't do any element merging\n    # can't use `defaults()` because it strips attributes\n    missing <- setdiff(names(default), names(theme))\n    theme[missing] <- default[missing]\n  } else {\n    # otherwise, we can just add the theme to the default theme\n    theme <- default + theme\n  }\n\n  # if we're still missing elements relative to fallback default, fill in those\n  missing <- setdiff(names(ggplot_global$theme_default), names(theme))\n  theme[missing] <- ggplot_global$theme_default[missing]\n\n  # Check that all elements have the correct class (element_text, unit, etc)\n  check_theme(theme)\n\n  # Remove elements that are not registered\n  # We accept unregistered `geom.*` elements\n  remove <- setdiff(names(theme), names(get_element_tree()))\n  remove <- remove[!startsWith(remove, \"geom.\")]\n  theme[remove] <- NULL\n  theme\n}"

const rtdal002244Source0011 = `add_theme <- function(t1, t2, t2name, call = caller_env()) {
  if (is.null(t2)) {
    return(t1)
  }
  if (!is.list(t2)) { # in various places in the code base, simple lists are used as themes
    cli::cli_abort("Can't add {.arg {t2name}} to a theme object.", call = call)
  }

  # If t2 is a complete theme or t1 is NULL, just return t2
  if (is_theme_complete(t2) || is.null(t1))
    return(t2)

  # Iterate over the elements that are to be updated
  try_fetch(
    for (item in names(t2)) {
      x <- merge_element(t2[[item]], t1[[item]])

      # Assign it back to t1
      # This is like doing t1[[item]] <- x, except that it preserves NULLs.
      # The other form will simply drop NULL values
      t1[item] <- list(x)
    },
    error = function(cnd) {
      cli::cli_abort("Can't merge the {.var {item}} theme element.", parent = cnd, call = call)
    }
  )

  if (!is_theme(t1) && is.list(t1)) {
    t1 <- theme(!!!t1)
  }

  # Only validate if both themes should be validated
  t1@validate <- is_theme_validate(t1) && is_theme_validate(t2)

  t1
}`

const rtdal002244Source0012 = "calc_element <- function(element, theme, verbose = FALSE, skip_blank = FALSE,\n                         call = caller_env()) {\n  if (verbose) cli::cli_inform(paste0(element, \" --> \"))\n\n  el_out <- theme[[element]]\n\n  # If result is element_blank, we skip it if `skip_blank` is `TRUE`,\n  # and otherwise we don't inherit anything from parents\n  if (is_theme_element(el_out, \"blank\")) {\n    if (isTRUE(skip_blank)) {\n      el_out <- NULL\n    } else {\n      if (verbose) cli::cli_inform(\"{.fn element_blank} (no inheritance)\")\n      return(el_out)\n    }\n  }\n\n  # Obtain the element tree\n  element_tree <- get_element_tree()\n\n  # If the element is defined (and not just inherited), check that\n  # it is of the class specified in element_tree\n  if (!is.null(el_out)) {\n    class <- element_tree[[element]]$class\n    if (inherits(class, \"S7_class\")) {\n      old_s3_inherit <- inherits(el_out, class@name)\n      if (!S7::S7_inherits(el_out, class) && !old_s3_inherit) {\n        cli::cli_abort(\"Theme element {.var {element}} must have class {.cls {class@name}}.\", call = call)\n      }\n    } else {\n      if (!inherits(el_out, class)) {\n        cli::cli_abort(\"Theme element {.var {element}} must have class {.cls {ggplot_global$element_tree[[element]]$class}}.\", call = call)\n      }\n    }\n  }\n\n  # Get the names of parents from the inheritance tree\n  pnames <- element_tree[[element]]$inherit\n\n  # If no parents, this is a \"root\" node. Just return this element.\n  if (is.null(pnames)) {\n    if (verbose) cli::cli_inform(\"nothing (top level)\")\n\n    # Check that all the properties of this element are non-NULL\n    if (is_theme_element(el_out)) {\n      nullprops <- lengths(S7::props(el_out)) == 0\n    } else {\n      nullprops <- vapply(el_out, is.null, logical(1))\n    }\n    if (!any(nullprops)) {\n      return(el_out) # no null properties, return element as is\n    }\n\n    # if we have null properties, try to fill in from ggplot_global$theme_default\n    el_out <- combine_elements(el_out, ggplot_global$theme_default[[element]])\n    if (is_theme_element(el_out)) {\n      nullprops <- lengths(S7::props(el_out)) == 0\n    } else {\n      nullprops <- vapply(el_out, is.null, logical(1))\n    }\n    if (is_theme_element(el_out, \"geom\")) {\n      # Geom elements are expected to have NULL fill/colour, so allow these\n      # to be missing\n      nullprops[c(\"colour\", \"fill\")] <- FALSE\n    }\n    if (!any(nullprops)) {\n      return(el_out) # no null properties remaining, return element\n    }\n\n    cli::cli_abort(\"Theme element {.var {element}} has {.code NULL} property without default: {.field {names(nullprops)[nullprops]}}.\", call = call)\n  }\n\n  # Calculate the parent objects' inheritance\n  if (verbose) cli::cli_inform(\"{pnames}\")\n\n  # once we've started skipping blanks, we continue doing so until the end of the\n  # recursion; we initiate skipping blanks if we encounter an element that\n  # doesn't inherit blank.\n  skip_blank <- skip_blank ||\n    (!is.null(el_out) && !isTRUE(try_prop(el_out, \"inherit.blank\")))\n\n  parents <- lapply(\n    pnames,\n    calc_element,\n    theme,\n    verbose = verbose,\n    skip_blank = skip_blank,\n    call = call\n  )\n\n  # Combine the properties of this element with all parents\n  Reduce(combine_elements, parents, el_out)\n}"

const rtdal002244Source0013 = `merge_element <- S7::new_generic(
  "merge_element", dispatch_args = c("new", "old"),
  fun = function(new, old, ...) {
    # If old is NULL or element_blank, then just return new
    if (is.null(old) || is_theme_element(old, "blank")) {
      return(new)
    }
    S7::S7_dispatch()
  }
)`

const rtdal002244Source0014 = `S7::method(merge_element, list(S7::class_any, S7::class_any))  <-
  function(new, old, ...) {
    if (is.null(new) || is.character(new) || is.numeric(new) || is.unit(new) ||
        is.logical(new) || is.function(new)) {
      # If new is NULL, or a string, numeric vector, unit, or logical, just return it
      return(new)
    }

    # otherwise we can't merge
    cli::cli_abort("No method for merging {.cls {class(new)[1]}} into {.cls {class(old)[1]}}.")
  }`

const rtdal002244Source0015 = `S7::method(merge_element, list(element_blank, S7::class_any)) <-
  function(new, old, ...) {
    # If new is element_blank, just return it
    new
  }`

const rtdal002244Source0016 = `S7::method(merge_element, list(element, S7::class_any)) <-
  function(new, old, ...) {
    # actual merging can only happen if classes match
    if (!inherits(new, class(old)[1])) {
      cli::cli_abort("Only elements of the same class can be merged.")
    }

    # Override NULL properties of new with the values in old
    # Get logical vector of NULL properties in new
    idx <- lengths(S7::props(new)) == 0
    # Get the names of TRUE items
    idx <- names(idx[idx])

    # Update non-NULL items
    S7::props(new)[idx] <- S7::props(old, idx)

    new
}`

const rtdal002244Source0017 = `S7::method(merge_element, list(margin, S7::class_any)) <-
  function(new, old, ...) {
    if (anyNA(new) && is_margin(old)) {
      new[is.na(new)] <- old[is.na(new)]
    }
    new
  }`

const rtdal002244Source0018 = `S7::method(merge_element, list(S7::new_S3_class("element"), S7::class_any)) <-
  function(new, old, ...) {
    if (S7::S7_inherits(old)) {
      old <- S7::props(old)
    }
    idx <- lengths(new) == 0
    idx <- names(idx[idx])
    new[idx] <- old[idx]
    new
  }`

const rtdal002244Source0019 = `combine_elements <- function(e1, e2) {

  # If e2 is NULL, nothing to inherit
  if (is.null(e2) || is_theme_element(e1, "blank")) {
    return(e1)
  }

  # If e1 is NULL inherit everything from e2
  if (is.null(e1)) {
    return(e2)
  }

  # Inheritance of rel objects
  if (is_rel(e1)) {
    # Both e1 and e2 are rel, give product as another rel
    if (is_rel(e2)) {
      return(rel(unclass(e1) * unclass(e2)))
    }
    # If e2 is a unit/numeric, return modified unit/numeric
    # Note that unit objects are considered numeric
    if (is.numeric(e2) || is.unit(e2)) {
      return(unclass(e1) * e2)
    }
    return(e1)
  }

  if (is_margin(e1) && is_margin(e2)) {
    if (anyNA(e2)) {
      e2[is.na(e2)] <- unit(0, "pt")
    }
    if (anyNA(e1)) {
      e1[is.na(e1)] <- e2[is.na(e1)]
    }
  }

  # Backward compatbility
  # TODO: deprecate next release cycle
  is_old_element <- !S7::S7_inherits(e1) && inherits(e1, "element")
  if (is_old_element && (is_theme_element(e2) || inherits(e2, "element"))) {
    return(combine_s3_elements(e1, e2))
  }

  # If neither of e1 or e2 are element_* objects, return e1
  if (!is_theme_element(e1) && !is_theme_element(e2)) {
    return(e1)
  }

  # If e2 is element_blank, and e1 inherits blank inherit everything from e2,
  # otherwise ignore e2
  if (is_theme_element(e2, "blank")) {
    if (isTRUE(try_prop(e1, "inherit.blank"))) {
      return(e2)
    } else {
      return(e1)
    }
  }

  parent_props <- if (S7::S7_inherits(e2)) S7::props(e2) else unclass(e2)

  # If e1 has any NULL properties, inherit them from e2
  n <- S7::prop_names(e1)[lengths(S7::props(e1)) == 0]
  S7::props(e1)[n] <- parent_props[n]

  # Calculate relative sizes
  if (is_rel(try_prop(e1, "size"))) {
    e1@size <- parent_props$size * unclass(e1@size)
  }

  # Calculate relative linewidth
  if (is_rel(try_prop(e1, "linewidth"))) {
    e1@linewidth <- parent_props$linewidth * unclass(e1@linewidth)
  }

  if (is_theme_element(e1, "text")) {
    e1@margin <- combine_elements(e1@margin, parent_props$margin)
  }

  # If e2 is 'richer' than e1, fill e2 with e1 parameters
  is_subclass <- !any(inherits(e2, class(e1), which = TRUE) == 0)
  is_subclass <- is_subclass && length(setdiff(class(e2), class(e1))) > 0
  if (is_subclass) {
    new <- defaults(S7::props(e1), S7::props(e2))
    S7::props(e2)[names(new)] <- new
    return(e2)
  }

  e1
}`

const rtdal002244Source0020 = `combine_s3_elements <- function(e1, e2) {
  e1 <- merge_element(e1, e2)
  if (S7::S7_inherits(e2)) {
    e2 <- S7::props(e2)
  }
  if (is_rel(e1$size)) {
    e1$size <- e2$size * unclass(e1$size)
  }
  if (is_rel(e1$linewidth)) {
    e1$linewidth <- e2$linewidth * unclass(e1$linewidth)
  }
  if (inherits(e1, "element_text")) {
    e1$margin <- combine_elements(e1$margin, e2$margin)
  }
  return(e1)
}`

