const rtdal002252Source0002 = `"%||%" <- function(a, b) {
  if (!is.null(a)) a else b
}`

const rtdal002252Source0003 = `"%|W|%" <- function(a, b) {
  if (!is_waiver(a)) a else b
}`

const rtdal002252Source0004 = "check_required_aesthetics <- function(required, present, name, call = caller_env()) {\n  if (is.null(required)) {\n    return()\n  }\n\n  required <- strsplit(required, \"|\", fixed = TRUE)\n  n <- lengths(required)\n\n  is_present <- vapply(\n    required,\n    function(req) any(req %in% present),\n    logical(1)\n  )\n  if (all(is_present)) {\n    return()\n  }\n\n  # Deal with paired (bidirectional) aesthetics\n  pairs <- character()\n  missing_pairs <- n == 2\n  if (any(missing_pairs)) {\n    pairs <- lapply(required[missing_pairs], rep_len, 2)\n    pairs <- list(\n      vapply(pairs, `[`, character(1), 1),\n      vapply(pairs, `[`, character(1), 2)\n    )\n    pairs <- lapply(pairs, setdiff, present)\n    pairs <- vapply(pairs, function(x) {\n      as_cli(\"{.and {.field {x}}}\")\n    }, character(1))\n    pairs <- as_cli(\"{.or {pairs}}\")\n  }\n\n  other <- character()\n  missing_other <- !is_present & n != 2\n  if (any(missing_other)) {\n    other <- lapply(required[missing_other], setdiff, present)\n    other <- vapply(other, function(x) {\n      as_cli(\"{.or {.field {x}}}\")\n    }, character(1))\n  }\n\n  missing <- c(other, pairs)\n\n  cli::cli_abort(\n    \"{.fn {name}} requires the following missing aesthetics: {.and {missing}}.\",\n    call = call\n  )\n}"

const rtdal002252Source0006 = `remove_missing <- function(df, na.rm = FALSE, vars = names(df), name = "",
                           finite = FALSE) {
  check_bool(na.rm)
  missing <- detect_missing(df, vars, finite)

  if (any(missing)) {
    df <- df[!missing, , drop = FALSE]
    if (!na.rm) {
      if (name != "") name <- paste(" ({.fn ", name, "})", sep = "")
      msg <- paste0(
        "Removed {sum(missing)} row{?s} containing ",
        if (finite) "non-finite" else "missing values or values",
        " outside the scale range", name, "."
      )
      cli::cli_warn(msg)
    }
  }

  df
}`

const rtdal002252Source0007 = `detect_missing <- function(df, vars, finite = FALSE) {
  vars <- intersect(vars, names(df))
  !cases(df[, vars, drop = FALSE], if (finite) is_finite else is_complete)
}`

const rtdal002252Source0008 = `cases <- function(x, fun) {
  ok <- vapply(x, fun, logical(nrow(x)))

  # Need a special case test when x has exactly one row, because rowSums
  # doesn't respect dimensions for 1x1 matrices. vapply returns a vector (not
  # a matrix when the input has one row.
  if (is.vector(ok)) {
    all(ok)
  } else {
    # Find all the rows where all are TRUE
    rowSums(as.matrix(ok)) == ncol(x)
  }
}`

const rtdal002252Source0009 = `is_finite <- function(x) {
  if (typeof(x) == "list") {
    !vapply(x, is.null, logical(1))
  } else if (typeof(x) == "character") {
    !is.na(x)
  } else {
    is.finite(x)
  }
}`

const rtdal002252Source0010 = `is_complete <- function(x) {
  if (typeof(x) == "list") {
    !vapply(x, is.null, logical(1))
  } else {
    !is.na(x)
  }
}`

