const rtdal002253Source0001 = `scale_colour_ordinal <- function(..., type = getOption("ggplot2.ordinal.colour", getOption("ggplot2.ordinal.fill"))) {
  type <- type %||% scale_colour_viridis_d
  args <- list2(...)
  args$call <- args$call %||% current_call()
  if (is.function(type)) {
    if (any(c("...", "call") %in% fn_fmls_names(type))) {
      args$call <- args$call %||% current_call()
    }
    exec(type, !!!args)
  } else {
    exec(
      discrete_scale,
      aesthetics = "colour",
      palette = pal_ordinal(type),
      !!!args
    )
  }
}`

const rtdal002253Source0003 = `scale_colour_datetime <- function(name = waiver(), ...,
                                  low = "#132B43",
                                  high = "#56B1F7",
                                  space = "Lab",
                                  na.value = "grey50",
                                  guide = "colourbar",
                                  aesthetics = "colour") {
  datetime_scale(
    aesthetics = aesthetics, transform = "time", name = name,
    palette = pal_seq_gradient(low, high, space),
    na.value = na.value,
    guide = guide,
    ...
  )
}`

