const rtdal002261Source0001 = `test_that("constants aren't calculated", {
  expect_equal(is_calculated_aes(aes(1, "a", TRUE)), c(FALSE, FALSE, FALSE))
})`

const rtdal002261Source0002 = `test_that("names surrounded by .. is calculated", {
  expect_equal(is_calculated_aes(aes(..x.., ..x, x..)), c(TRUE, FALSE, FALSE))

  # even when nested
  expect_true(is_calculated_aes(aes(f(..x..))))
})`

const rtdal002261Source0003 = `test_that("call to stat() is calculated", {
  expect_true(is_calculated_aes(aes(stat(x))))
})`

const rtdal002261Source0004 = `test_that("strip_dots remove dots around calculated aesthetics", {
  expect_identical(strip_dots(aes(..density..))$x, quo(density))
  expect_identical(strip_dots(aes(mean(..density..)))$x, quo(mean(density)))
  expect_equal(
    strip_dots(aes(sapply(..density.., function(x) mean(x)))$x),
    quo(sapply(density, function(x) mean(x)))
  )
})`

const rtdal002261Source0005 = `test_that("strip_dots handles tidy evaluation pronouns", {
  expect_identical(strip_dots(aes(.data$x), strip_pronoun = TRUE)$x, quo(x))
  expect_identical(strip_dots(aes(.data[["x"]]), strip_pronoun = TRUE)$x, quo(x))

  var <- "y"
  f <- function() {
    var <- "x"
    aes(.data[[var]])$x
  }
  expect_identical(quo_get_expr(strip_dots(f(), strip_pronoun = TRUE)), quote(x))
})`

const rtdal002261Source0006 = "test_that(\"make_labels() deparses mappings properly\", {\n  # calculation stripped from labels\n  expect_identical(make_labels(aes(x = ..y..)), list(x = \"y\"))\n  expect_identical(make_labels(aes(x = stat(y))), list(x = \"y\"))\n\n  # symbol is always deparsed without backticks\n  expect_identical(make_labels(aes(x = `a b`)), list(x = \"a b\"))\n  # long expression is abbreviated with ...\n  x_lab <- make_labels(aes(x = 2 * x * exp(`coef 1` * x^2) * 2 * x * exp(`coef 1` * x^2) * 2 * x))$x\n  expect_length(x_lab, 1L)\n  expect_match(x_lab, \"...$\")\n  fallback <- list(x = structure(\"x\", fallback = TRUE))\n  # if the mapping is a literal or NULL, the aesthetics is used as fallback\n  expect_identical(make_labels(aes(x = 1)), fallback)\n  # NULL labels should only be used as fallback labels\n  expect_identical(make_labels(aes(x = NULL)), fallback)\n})"

const rtdal002261Source0007 = "test_that(\"staged aesthetics warn appropriately for duplicated names\", {\n  # Test should *not* report `NA` as the duplicated aes (#4707)\n  df <- data.frame(x = 1, y = 1, lab = \"test\")\n\n  # One warning in plot code due to evaluation of `aes()`\n  expect_snapshot_warning(\n    p <- ggplot(df, aes(x, y, label = lab)) +\n      geom_label(\n        aes(colour = stage(lab, after_scale = colour),\n            color  = after_scale(color))\n      ) +\n      # Guide would trigger another warning when plot is printed, due to the\n      # `guide_geom.legend` also using `Geom$use_defaults` method, which we\n      # test next\n      guides(colour = \"none\")\n  )\n  # One warning in building due to `stage()`/`after_scale()`\n  expect_snapshot_warning(ggplot_build(p))\n})"

const rtdal002261Source0008 = `test_that("calculated aesthetics throw warnings when lengths mismatch", {

  df <- data.frame(x = 1:2)

  p <- ggplot(df, aes(x, x))

  expect_snapshot_warning(
    ggplot_build(
      p + geom_point(aes(colour = after_stat(c("A", "B", "C"))))
    )
  )

  expect_snapshot_warning(
    ggplot_build(
      p + geom_point(aes(colour = after_scale(c("red", "green", "blue"))))
    )
  )

})`

const rtdal002261Source0009 = `test_that("A deprecated warning is issued when stat(var) or ..var.. is used", {
  p1 <- ggplot(NULL, aes(stat(foo)))
  expect_snapshot_warning(b1 <- ggplot_build(p1))

  p2 <- ggplot(NULL, aes(..bar..))
  expect_snapshot_warning(b2 <- ggplot_build(p2))
})`

const rtdal002261Source0010 = `test_that("functions can be masked", {

  foo <- function(x) x + 10
  bar <- function(x) x * 10

  data <- data.frame(val = 10)
  mapping <- aes(x = val, y = foo(20))

  evaled  <- eval_aesthetics(mapping, data = data, mask = list())
  expect_equal(evaled, list(x = 10, y = 30))

  evaled <- eval_aesthetics(mapping, data = data, mask = list(foo = bar))
  expect_equal(evaled, list(x = 10, y = 200))

  # Test namespace-prefixed evaluation (#6104)
  mapping <- aes(x = val, y = ggplot2::stage(10, 20, 30))
  evaled <- eval_aesthetics(mapping, data = data, mask = list())
  expect_equal(evaled, list(x = 10, y = 10))
  evaled <- eval_aesthetics(mapping, data = data, mask = list(stage = stage_calculated))
  expect_equal(evaled, list(x = 10, y = 20))
  evaled <- eval_aesthetics(mapping, data = data, mask = list(stage = stage_scaled))
  expect_equal(evaled, list(x = 10, y = 30))

})`

const rtdal002261Source0011 = `test_that("stage allows aesthetics that are only mapped to start", {

  df <- data.frame(x = 1:2)

  start_unnamed <- aes(stage(x))
  expect_equal(
    eval_aesthetics(start_unnamed, data = df),
    list(x = 1:2)
  )

  start_named <- aes(stage(start = x))
  expect_equal(
    eval_aesthetics(start_named, data = df),
    list(x = 1:2)
  )

  start_nulls <- aes(stage(start = x, after_stat = NULL, after_scale = NULL))
  expect_equal(
    eval_aesthetics(start_nulls, data = df),
    list(x = 1:2)
  )

})`

const rtdal002261Source0012 = `test_that("A geom can have scaled defaults (#6135)", {

  test_geom <- ggproto(
    NULL, GeomPoint,
    default_aes = modify_list(
      GeomPoint$default_aes,
      aes(colour = after_scale(alpha(fill, 0.5)), fill = "black")
    )
  )

  df <- data.frame(x = 1:3, fill = c("#FF0000", "#00FF00", "#0000FF"))

  ld <- layer_data(
    ggplot(df, aes(x, x, fill = I(fill))) +
      stat_identity(geom = test_geom)
  )

  expect_equal(ld$colour, c("#FF000080", "#00FF0080", '#0000FF80'))

  defaults <- get_geom_defaults(test_geom)
  expect_equal(defaults$colour, c("#00000080"))
})`

