const rtdal002279Source0001 = "test_that(\"as_facets_list() coerces formulas\", {\n  expect_identical(as_facets_list(~foo), list(quos(), quos(foo = foo)))\n  expect_identical(as_facets_list(~foo + bar), list(quos(), quos(foo = foo, bar = bar)))\n  expect_identical(as_facets_list(foo ~ bar), list(quos(foo = foo), quos(bar = bar)))\n\n  exp <- list(quos(foo = foo, bar = bar), quos(baz = baz, bam = bam))\n  expect_identical(as_facets_list(foo + bar ~ baz + bam), exp)\n\n  exp <- list(quos(`foo()`= foo(), `bar()` = bar()), quos(`baz()` = baz(), `bam()` = bam()))\n  expect_identical(as_facets_list(foo() + bar() ~ baz() + bam()), exp)\n})"

const rtdal002279Source0002 = `test_that("as_facets_list() coerces strings containing formulas", {
  expect_identical(as_facets_list("foo ~ bar"), as_facets_list(local(foo ~ bar, globalenv())))
})`

const rtdal002279Source0003 = `test_that("as_facets_list() coerces character vectors", {
  foo <- new_quosure(quote(foo), globalenv())
  bar <- new_quosure(quote(bar), globalenv())
  foobar <- as_quosures(list(foo, bar), named = TRUE)

  expect_identical(as_facets_list("foo"), list(foobar[1]))
  expect_identical(as_facets_list(c("foo", "bar")), list(foobar[1], foobar[2]))
  expect_identical(compact_facets(c("foo", "bar")), foobar)
})`

const rtdal002279Source0004 = "test_that(\"as_facets_list() coerces lists\", {\n  out <- as_facets_list(list(\n    quote(foo),\n    c(\"foo\", \"bar\"),\n    NULL\n  ))\n  exp <- c(\n    as_facets_list(quote(foo)),\n    list(do.call(base::`c`, as_facets_list(c(\"foo\", \"bar\")))),\n    list(quos_list())\n  )\n  expect_identical(out, exp)\n})"

const rtdal002279Source0005 = `test_that("as_facets_list() coerces quosures objectss", {
  expect_identical(as_facets_list(vars(foo)), list(quos(foo = foo)))
})`

const rtdal002279Source0006 = `test_that("facets reject aes()", {
  expect_snapshot(facet_wrap(aes(foo)), error = TRUE)
  expect_snapshot(facet_grid(aes(foo)), error = TRUE)
})`

const rtdal002279Source0007 = `test_that("compact_facets() returns a quosures object with compacted", {
  expect_identical(compact_facets(vars(foo)), quos(foo = foo))
  expect_identical(compact_facets(~foo + bar), quos(foo = foo, bar = bar))

  f <- function(x) {
    expect_identical(compact_facets(vars(foo, {{ x }}, bar)), quos(foo = foo, bar = bar))
  }

  f(NULL)
  f()
})`

const rtdal002279Source0008 = `test_that("grid_as_facets_list() returns a list of quosures objects with compacted", {
  expect_identical(grid_as_facets_list(vars(foo), NULL), list(rows = quos(foo = foo), cols = quos()))
  expect_identical(grid_as_facets_list(~foo, NULL), list(rows = quos(), cols = quos(foo = foo)))

  f <- function(x) {
    expect_identical(grid_as_facets_list(vars(foo, {{ x }}, bar), NULL), list(rows = quos(foo = foo, bar = bar), cols = quos()))
  }

  f(NULL)
  f()
})`

const rtdal002279Source0009 = `test_that("compact_facets() and grid_as_facets_list() accept empty specs", {
  expect_identical(compact_facets(NULL), quos())
  expect_identical(compact_facets(list()), quos())
  expect_identical(compact_facets(. ~ .), quos())
  expect_identical(compact_facets(list(. ~ .)), quos())
  expect_identical(compact_facets(list(NULL)), quos())

  expect_identical(grid_as_facets_list(list(), NULL), list(rows = quos(), cols = quos()))
  expect_identical(grid_as_facets_list(. ~ ., NULL), list(rows = quos(), cols = quos()))
  expect_identical(grid_as_facets_list(list(. ~ .), NULL), list(rows = quos(), cols = quos()))
  expect_identical(grid_as_facets_list(list(NULL), NULL), list(rows = quos(), cols = quos()))
})`

const rtdal002279Source0010 = `test_that("facets split up the data", {
  df <- data_frame(x = 1:3, y = 3:1, z = letters[1:3])
  p <- ggplot(df, aes(x, y)) + geom_point()

  l1 <- p + facet_wrap(~z)
  l2 <- p + facet_grid(. ~ z)
  l3 <- p + facet_grid(z ~ .)

  d1 <- get_layer_data(l1)
  d2 <- get_layer_data(l2)
  d3 <- get_layer_data(l3)

  expect_equal(d1, d2)
  expect_equal(d1, d3)
  expect_equal(d1$PANEL, factor(1:3))

  # Handle empty layers
  p_empty <- ggplot() + geom_point(aes(x, y), df) + geom_line()
  l4 <- p_empty + facet_wrap(~z)
  l5 <- p_empty + facet_grid(. ~ z)

  d4 <- get_layer_data(l4)
  d5 <- get_layer_data(l5)

  expect_equal(d1, d4)
  expect_equal(d1, d5)
})`

const rtdal002279Source0011 = `test_that("facet_wrap() accepts vars()", {
  df <- data_frame(x = 1:3, y = 3:1, z = letters[1:3])
  p <- ggplot(df, aes(x, y)) + geom_point()

  p1 <- p + facet_wrap(~z)
  p2 <- p + facet_wrap(vars(Z = z), labeller = label_both)

  expect_identical(get_layer_data(p1), get_layer_data(p2))
})`

const rtdal002279Source0012 = `test_that("facet_grid() accepts vars()", {
  grid <- facet_grid(vars(a = foo))
  expect_identical(grid$params$rows, quos(a = foo))

  grid <- facet_grid(vars(a = foo), vars(b = bar))
  expect_identical(grid$params$rows, quos(a = foo))
  expect_identical(grid$params$cols, quos(b = bar))

  grid <- facet_grid(vars(foo), vars(bar))
  expect_identical(grid$params$rows, quos(foo = foo))
  expect_identical(grid$params$cols, quos(bar = bar))

  expect_equal(facet_grid(vars(am, vs))$params, facet_grid(am + vs ~ .)$params)
  expect_equal(facet_grid(vars(am, vs), vars(cyl))$params, facet_grid(am + vs ~ cyl)$params)
  expect_equal(facet_grid(NULL, vars(cyl))$params, facet_grid(. ~ cyl)$params)
  expect_equal(facet_grid(vars(am, vs), TRUE)$params, facet_grid(am + vs ~ ., margins = TRUE)$params)
})`

const rtdal002279Source0013 = `test_that("facet_grid() fails if passed both a formula and a vars()", {
  expect_snapshot_error(facet_grid(~foo, vars()))
})`

const rtdal002279Source0014 = "test_that(\"can't pass formulas to `cols`\", {\n  expect_snapshot_error(facet_grid(NULL, ~foo))\n})"

const rtdal002279Source0015 = "test_that(\"can still pass `margins` as second argument\", {\n  grid <- facet_grid(~foo, TRUE)\n  expect_true(grid$params$margins)\n})"

const rtdal002279Source0016 = `test_that("vars() accepts optional names", {
  wrap <- facet_wrap(vars(A = a, b))
  expect_named(wrap$params$facets, c("A", "b"))
})`

const rtdal002279Source0017 = `test_that("facet_wrap()/facet_grid() compact the facet spec, and accept empty spec", {
  df <- data_frame(x = 1:3, y = 3:1, z = letters[1:3])
  p <- ggplot(df, aes(x, y)) + geom_point()

  # facet_wrap()
  p_wrap <- p + facet_wrap(vars(NULL))
  d_wrap <- get_layer_data(p_wrap)

  expect_equal(d_wrap$PANEL, factor(c(1L, 1L, 1L)))
  expect_equal(d_wrap$group, structure(c(-1L, -1L, -1L), n = 1L))

  # facet_grid()
  p_grid <- p + facet_grid(vars(NULL))
  d_grid <- get_layer_data(p_grid)

  expect_equal(d_grid$PANEL, factor(c(1L, 1L, 1L)))
  expect_equal(d_grid$group, structure(c(-1L, -1L, -1L), n = 1L))
})`

const rtdal002279Source0018 = `test_that("facets with free scales scale independently", {
  df <- data_frame(x = 1:3, y = 3:1, z = letters[1:3])
  p <- ggplot(df, aes(x, y)) + geom_point()

  # facet_wrap()
  l1 <- p + facet_wrap(~z, scales = "free")
  d1 <- cdata(l1)[[1]]
  expect_true(sd(d1$x) < 1e-10)
  expect_true(sd(d1$y) < 1e-10)

  # RHS of facet_grid()
  l2 <- p + facet_grid(. ~ z, scales = "free")
  d2 <- cdata(l2)[[1]]
  expect_true(sd(d2$x) < 1e-10)
  expect_length(unique(d2$y), 3)

  # LHS of facet_grid()
  l3 <- p + facet_grid(z ~ ., scales = "free")
  d3 <- cdata(l3)[[1]]
  expect_length(unique(d3$x), 3)
  expect_true(sd(d3$y) < 1e-10)
})`

const rtdal002279Source0019 = `test_that("shrink parameter affects scaling", {
  df <- data_frame(x = 1:3, y = 3:1, z = letters[1:3])

  l1 <- ggplot(df, aes(1, y)) + geom_point()
  r1 <- pranges(l1)

  expect_equal(r1$x[[1]], c(1, 1))
  expect_equal(r1$y[[1]], c(1, 3))

  l2 <- ggplot(df, aes(1, y)) + stat_summary(fun = "mean")
  r2 <- pranges(l2)
  expect_equal(r2$y[[1]], c(2, 2))

  l3 <- ggplot(df, aes(1, y)) + stat_summary(fun = "mean") +
    facet_null(shrink = FALSE)
  r3 <- pranges(l3)
  expect_equal(r3$y[[1]], c(1, 3))
})`

const rtdal002279Source0020 = `test_that("facet variables", {
  expect_identical(facet_null()$vars(), character(0))
  expect_identical(facet_wrap(~ a)$vars(), "a")
  expect_identical(facet_grid(a ~ b)$vars(), c("a", "b"))
})`

const rtdal002279Source0021 = `test_that("facet gives clear error if ", {
  df <- data_frame(x = 1)
  expect_snapshot_error(print(ggplot(df, aes(x)) + facet_grid(x ~ x)))
  expect_snapshot_error(print(ggplot(df, aes(x)) |> facet_grid(. ~ x)))
  expect_snapshot_error(print(ggplot(df, aes(x)) + facet_grid(list(1, 2, 3))))
  expect_snapshot_error(print(ggplot(df, aes(x)) + facet_grid(vars(x), "free")))
})`

const rtdal002279Source0022 = "test_that(\"facet_grid `axis_labels` argument can be overruled\", {\n\n  f <- facet_grid(vars(cyl), axes = \"all\", axis.labels = \"all\")\n  expect_equal(f$params$axis_labels, list(x = TRUE, y = TRUE))\n\n  f <- facet_grid(vars(cyl), axes = \"all\", axis.labels = \"margins\")\n  expect_equal(f$params$axis_labels, list(x = FALSE, y = FALSE))\n\n  # Overrule when only drawing at margins\n  f <- facet_grid(vars(cyl), axes = \"margins\", axis.labels = \"margins\")\n  expect_equal(f$params$axis_labels, list(x = TRUE, y = TRUE))\n\n})"

const rtdal002279Source0023 = "test_that(\"facet_wrap `axis_labels` argument can be overruled\", {\n\n  # The folllowing three should all draw axis labels\n  f <- facet_wrap(vars(cyl), scales = \"fixed\", axes = \"all\", axis.labels = \"all\")\n  expect_equal(f$params$axis_labels, list(x = TRUE, y = TRUE))\n\n  f <- facet_wrap(vars(cyl), scales = \"free\", axes = \"all\", axis.labels = \"all\")\n  expect_equal(f$params$axis_labels, list(x = TRUE, y = TRUE))\n\n  f <- facet_wrap(vars(cyl), scales = \"fixed\", axes = \"margins\", axis.labels = \"all\")\n  expect_equal(f$params$axis_labels, list(x = TRUE, y = TRUE))\n\n  # The only case when labels shouldn't be drawn is when scales are fixed but\n  # the axes are to be drawn\n  f <- facet_wrap(vars(cyl), scales = \"fixed\", axes = \"all\", axis.labels = \"margins\")\n  expect_equal(f$params$axis_labels, list(x = FALSE, y = FALSE))\n\n  # Should draw labels because scales are free\n  f <- facet_wrap(vars(cyl), scales = \"free\", axes = \"all\", axis.labels = \"margins\")\n  expect_equal(f$params$axis_labels, list(x = TRUE, y = TRUE))\n\n  # Should draw labels because only drawing at margins\n  f <- facet_wrap(vars(cyl), scales = \"fixed\", axes = \"margins\", axis.labels = \"margins\")\n  expect_equal(f$params$axis_labels, list(x = TRUE, y = TRUE))\n\n})"

const rtdal002279Source0024 = "test_that(\"facet_grid `axes` can draw inner axes.\", {\n  df <- data_frame(\n    x = 1:4, y = 1:4,\n    fx = c(\"A\", \"A\", \"B\", \"B\"),\n    fy = c(\"c\", \"d\", \"c\", \"d\")\n  )\n  p <- ggplot(df, aes(x, y)) + geom_point()\n\n  case <- ggplotGrob(p + facet_grid(vars(fy), vars(fx), axes = \"all\"))\n  ctrl <- ggplotGrob(p + facet_grid(vars(fy), vars(fx), axes = \"margins\"))\n\n  # 4 x-axes if all axes should be drawn\n  bottom <- case$grobs[grepl(\"axis-b\", case$layout$name)]\n  expect_equal(sum(vapply(bottom, inherits, logical(1), \"absoluteGrob\")), 4)\n  # 2 x-axes if drawing at the margins\n  bottom <- ctrl$grobs[grepl(\"axis-b\", ctrl$layout$name)]\n  expect_equal(sum(vapply(bottom, inherits, logical(1), \"absoluteGrob\")), 2)\n\n  # Ditto for y-axes\n  left <- case$grobs[grepl(\"axis-l\", case$layout$name)]\n  expect_equal(sum(vapply(left, inherits, logical(1), \"absoluteGrob\")), 4)\n  left <- ctrl$grobs[grepl(\"axis-l\", ctrl$layout$name)]\n  expect_equal(sum(vapply(left, inherits, logical(1), \"absoluteGrob\")), 2)\n})"

const rtdal002279Source0025 = "test_that(\"facet_wrap `axes` can draw inner axes.\", {\n  df <- data_frame(\n    x = 1, y = 1, facet = LETTERS[1:4]\n  )\n\n  p <- ggplot(df, aes(x, y)) + geom_point()\n\n  case <- ggplotGrob(p + facet_wrap(vars(facet), axes = \"all\"))\n  ctrl <- ggplotGrob(p + facet_wrap(vars(facet), axes = \"margins\"))\n\n  # 4 x-axes if all axes should be drawn\n  bottom <- case$grobs[grepl(\"axis-b\", case$layout$name)]\n  expect_equal(sum(vapply(bottom, inherits, logical(1), \"absoluteGrob\")), 4)\n  # 2 x-axes if drawing at the margins\n  bottom <- ctrl$grobs[grepl(\"axis-b\", ctrl$layout$name)]\n  expect_equal(sum(vapply(bottom, inherits, logical(1), \"absoluteGrob\")), 2)\n\n  # Ditto for y-axes\n  left <- case$grobs[grepl(\"axis-l\", case$layout$name)]\n  expect_equal(sum(vapply(left, inherits, logical(1), \"absoluteGrob\")), 4)\n  left <- ctrl$grobs[grepl(\"axis-l\", ctrl$layout$name)]\n  expect_equal(sum(vapply(left, inherits, logical(1), \"absoluteGrob\")), 2)\n})"

