const rtdal002288Source0001 = `test_that("geom_boxplot range includes all outliers", {
  dat <- data_frame(x = 1, y = c(-(1:20) ^ 3, (1:20) ^ 3) )
  p <- ggplot_build(ggplot(dat, aes(x,y)) + geom_boxplot())

  miny <- p@layout$panel_params[[1]]$y.range[1]
  maxy <- p@layout$panel_params[[1]]$y.range[2]

  expect_true(miny <= min(dat$y))
  expect_true(maxy >= max(dat$y))

  # Unless specifically directed not to
  p <- ggplot_build(ggplot(dat, aes(x, y)) + geom_boxplot(outliers = FALSE))

  miny <- p@layout$panel_params[[1]]$y.range[1]
  maxy <- p@layout$panel_params[[1]]$y.range[2]

  expect_lte(maxy, max(dat$y))
  expect_gte(miny, min(dat$y))
})`

const rtdal002288Source0002 = `test_that("geom_boxplot works in both directions", {
  dat <- data_frame(x = 1, y = c(-(1:20) ^ 3, (1:20) ^ 3) )

  p <- ggplot(dat, aes(x, y)) + geom_boxplot()
  x <- get_layer_data(p)
  expect_false(x$flipped_aes[1])

  p <- ggplot(dat, aes(y, x)) + geom_boxplot()
  y <- get_layer_data(p)
  expect_true(y$flipped_aes[1])

  x$flipped_aes <- NULL
  y$flipped_aes <- NULL
  expect_identical(x, flip_data(y, TRUE))
})`

const rtdal002288Source0003 = `test_that("geom_boxplot for continuous x gives warning if more than one x (#992)", {
  dat <- expand.grid(x = 1:2, y = c(-(1:5) ^ 3, (1:5) ^ 3) )

  bplot <- function(aes = NULL, extra = list()) {
    ggplot_build(ggplot(dat, aes) + geom_boxplot(aes) + extra)
  }

  expect_snapshot(p <- bplot(aes(x, y)))
  expect_snapshot(p <- bplot(aes(x, y), facet_wrap(~x)))
  expect_snapshot(p <- bplot(aes(Sys.Date() + x, y)))

  expect_silent(bplot(aes(x, group = x, y)))
  expect_silent(bplot(aes(1, y)))
  expect_silent(bplot(aes(factor(x), y)))
  expect_silent(bplot(aes(x == 1, y)))
  expect_silent(bplot(aes(as.character(x), y)))
})`

const rtdal002288Source0004 = `test_that("can use US spelling of colour", {
  df <- data_frame(x = 1, y = c(1:5, 100))
  plot <- ggplot(df, aes(x, y)) + geom_boxplot(outlier.color = "red")

  gpar <- get_layer_grob(plot)[[1]]$children[[1]]$children[[1]]$gp
  expect_equal(gpar$col, "#FF0000FF")
})`

const rtdal002288Source0005 = `test_that("boxes with variable widths do not overlap", {
  df <- data_frame(
    value = 1:12,
    group = rep(c("a", "b", "c"), each = 4L),
    subgroup = rep(c("A", "B"), times = 6L)
  )

  p <- ggplot(df, aes(group, value, colour = subgroup)) +
    geom_boxplot(varwidth = TRUE)
  d <- get_layer_data(p)[c("xmin", "xmax")]
  xid <- find_x_overlaps(d)

  expect_false(any(duplicated(xid)))
})`

const rtdal002288Source0006 = `test_that("boxplots with a group size >1 error", {
  p <- ggplot(
    data_frame(x = "one value", y = 3, value = 4:6),
    aes(x, ymin = 0, lower = 1, middle = y, upper = value, ymax = 10)
  ) +
    geom_boxplot(stat = "identity")

  expect_equal(nrow(get_layer_data(p, 1)), 3)
  expect_snapshot_error(get_layer_grob(p, 1))
})`

const rtdal002288Source0007 = `test_that("boxplot draws correctly", {
  expect_doppelganger("outlier colours",
    ggplot(mtcars, aes(x = factor(cyl), y = drat, colour = factor(cyl))) + geom_boxplot(outlier.size = 5)
  )
  expect_doppelganger("staples",
    ggplot(mtcars, aes(x = factor(cyl), y = drat, colour = factor(cyl))) + geom_boxplot(staplewidth = 0.5)
  )
  expect_doppelganger(
    "customised style",
    ggplot(mpg, aes(class, displ, colour = class)) +
      geom_boxplot(
        outlier.shape = 6,
        whisker.linetype = 2,
        median.colour = "red",
        box.colour    = "black",
        staple.linewidth = 1,
        staplewidth = 0.25
      )
  )
})`

const rtdal002288Source0008 = `test_that("quantile.type changes hinges for small samples (unweighted)", {
  df <- data_frame(x = 1, y = c(1, 2, 3, 4))

  p_default <- ggplot(df, aes(x, y)) + stat_boxplot()
  d_default <- get_layer_data(p_default)

  p_t2 <- ggplot(df, aes(x, y)) + stat_boxplot(quantile.type = 2)
  d_t2 <- get_layer_data(p_t2)

  # Lower/upper hinges should differ under different quantile definitions
  expect_false(isTRUE(all.equal(d_default$lower, d_t2$lower)))
  expect_false(isTRUE(all.equal(d_default$upper, d_t2$upper)))
})`

const rtdal002288Source0009 = `test_that("quantile.type = 7 matches default behavior (backward compatible)", {
  set.seed(123)
  df <- data_frame(x = 1, y = rnorm(25))

  p_default <- ggplot(df, aes(x, y)) + stat_boxplot()
  d_default <- get_layer_data(p_default)

  p_t7 <- ggplot(df, aes(x, y)) + stat_boxplot(quantile.type = 7)
  d_t7 <- get_layer_data(p_t7)

  expect_equal(d_default$lower, d_t7$lower)
  expect_equal(d_default$middle, d_t7$middle)
  expect_equal(d_default$upper, d_t7$upper)
})`

